public with sharing class ContactTriggerHandler {

    private final List<Contact> newList;
    private final Boolean isInsert;
    private final Boolean isUpdate;

    public ContactTriggerHandler() {
        this.newList = Trigger.new;
        this.isInsert = Trigger.isInsert;
        this.isUpdate = Trigger.isUpdate;
    }

    public void run() {
        if (Trigger.isBefore) {
            handleBeforeInsertOrUpdate();
        } else if (Trigger.isAfter && Trigger.isInsert) {
            handleAfterInsert();
        }
    }

    /**
     * Before insert/update: copy BillingCountry into MailingCountry (when blank)
     * and, on insert only, AccountSource into LeadSource (when blank) for
     * contacts related to an account.
     *
     * Bulk-safe: a single SOQL query collects all referenced accounts.
     */
    private void handleBeforeInsertOrUpdate() {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newList) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT BillingCountry, AccountSource FROM Account WHERE Id IN :accountIds]
        );

        for (Contact c : newList) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null) {
                // Account deleted or not visible; nothing to copy.
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    /**
     * After insert: when the related account has no phone, set the account's
     * phone from the contact's phone. If several new contacts of the same
     * account qualify, the first one in trigger order wins.
     *
     * Bulk-safe: a single SOQL query collects all candidate accounts and a
     * single DML statement updates all affected accounts.
     */
    private void handleAfterInsert() {
        // Accounts that have at least one new contact with a phone.
        Set<Id> candidateAccountIds = new Set<Id>();
        for (Contact c : newList) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                candidateAccountIds.add(c.AccountId);
            }
        }

        if (candidateAccountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, Phone FROM Account WHERE Id IN :candidateAccountIds]
        );

        // First qualifying contact per account (in trigger order) wins:
        // we only put an entry if the account has no entry yet and its
        // current phone is blank.
        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Contact c : newList) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            Account a = accountsById.get(c.AccountId);
            if (a == null || String.isNotBlank(a.Phone)) {
                continue;
            }
            if (!accountsToUpdate.containsKey(c.AccountId)) {
                accountsToUpdate.put(
                    c.AccountId,
                    new Account(Id = c.AccountId, Phone = c.Phone)
                );
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate.values();
        }
    }
}
