public inherited sharing class ExchangeRateClient {

    private static final String NAMED_CREDENTIAL_BASE = 'callout:FB_Exchange_Rates';
    private static final String PATH = '/v1/latest';
    private static final Integer MAX_ATTEMPTS = 2; // initial request + one retry on 503
    private static final Integer SERVICE_UNAVAILABLE = 503;
    private static final Integer OK = 200;

    public class ExchangeRateException extends Exception {}

    /**
     * Fetches FX rates for the requested quote currencies against the given base currency.
     *
     * @param baseCurrency     the base currency code, e.g. 'EUR'
     * @param quoteCurrencies  the set of quote currency codes, e.g. {'USD','GBP'}
     * @return map from each requested (normalised) quote code to its rate
     * @throws ExchangeRateException for invalid input (no callout attempted), non-200
     *         responses, unparsable bodies or missing rates
     */
    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        // ---- Validate & normalise input (before any callout) ----
        String baseCode = normalise(baseCurrency);
        if (!isValidCode(baseCode)) {
            throw new ExchangeRateException('Invalid base currency code: \'' + baseCurrency + '\'');
        }
        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('Quote currency set must not be null or empty');
        }

        // Normalise, validate and de-duplicate the quote codes; keep a deterministic order.
        List<String> quoteCodes = new List<String>();
        for (String rawQuote : quoteCurrencies) {
            String quote = normalise(rawQuote);
            if (!isValidCode(quote)) {
                throw new ExchangeRateException('Invalid quote currency code: \'' + rawQuote + '\'');
            }
            if (!quoteCodes.contains(quote)) {
                quoteCodes.add(quote);
            }
        }

        // ---- Build request ----
        String endpoint = NAMED_CREDENTIAL_BASE + PATH
            + '?base=' + EncodingUtil.urlEncode(baseCode, 'UTF-8')
            + '&symbols=' + EncodingUtil.urlEncode(String.join(quoteCodes, ','), 'UTF-8');

        HttpRequest request = new HttpRequest();
        request.setEndpoint(endpoint);
        request.setMethod('GET');
        request.setHeader('Accept', 'application/json');
        request.setTimeout(60000);

        Http http = new Http();

        // ---- Execute with a single retry on 503 ----
        Integer attempt = 0;
        HttpResponse response;
        while (attempt < MAX_ATTEMPTS) {
            attempt++;
            response = http.send(request);
            if (response.getStatusCode() != SERVICE_UNAVAILABLE) {
                break;
            }
            // 503: if this was the last allowed attempt we fall through and fail below.
        }

        if (response.getStatusCode() != OK) {
            throw new ExchangeRateException('Exchange rate service returned HTTP status '
                + response.getStatusCode() + ': ' + response.getBody());
        }

        // ---- Parse response ----
        Map<String, Object> parsed;
        try {
            parsed = (Map<String, Object>) JSON.deserializeUntyped(response.getBody());
        } catch (Exception e) {
            throw new ExchangeRateException('Unable to parse exchange rate response body: ' + e.getMessage());
        }

        Object ratesRaw = parsed.get('rates');
        Map<String, Object> rates;
        if (ratesRaw instanceof Map<String, Object>) {
            rates = (Map<String, Object>) ratesRaw;
        } else {
            throw new ExchangeRateException('Unable to parse exchange rate response body: missing or invalid "rates" object');
        }

        // ---- Build result only from requested codes (extra rates ignored) ----
        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String quote : quoteCodes) {
            if (!rates.containsKey(quote) || rates.get(quote) == null) {
                throw new ExchangeRateException('No rate returned for requested currency: ' + quote);
            }
            try {
                result.put(quote, Decimal.valueOf(String.valueOf(rates.get(quote))));
            } catch (Exception e) {
                throw new ExchangeRateException('Unable to parse rate for currency ' + quote + ': ' + rates.get(quote));
            }
        }
        return result;
    }

    private static String normalise(String code) {
        return code == null ? null : code.trim().toUpperCase();
    }

    private static Boolean isValidCode(String code) {
        return code != null && code.matches('^[A-Z]{3}$');
    }
}
