/**
 * Service class that groups Contacts of given Accounts by the (lower-cased)
 * domain part of their email address.
 *
 * - Runs WITH sharing so only records visible to the running user are returned.
 * - Bulk-safe: a single SOQL query for any number of Account Ids (no SOQL/DML in loops).
 * - Contacts without an Email are excluded; contacts whose Email has no valid
 *   domain part (no '@' or nothing after the '@') are also excluded.
 */
public with sharing class ContactDomainService {

    /**
     * Returns the contacts of the given accounts grouped by the domain part of
     * their email address, lower-cased (e.g. 'Jane@Example.COM' -> 'example.com').
     *
     * @param accountIds set of Account Ids; null or empty yields an empty map
     * @return map of email domain -> list of Contacts with Id, Email and AccountId populated
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> domainToContacts = new Map<String, List<Contact>>();

        // Null or empty input: return an empty map without querying.
        if (accountIds == null || accountIds.isEmpty()) {
            return domainToContacts;
        }

        // Respect the running user's sharing (class is declared `with sharing`)
        // and FLS (stripInaccessible removes fields the user cannot read).
        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email != null
        ];
        contacts = (List<Contact>) Security.stripInaccessible(
            AccessType.READABLE,
            contacts
        ).getRecords();

        for (Contact c : contacts) {
            String email = c.Email;
            if (String.isBlank(email)) {
                continue;
            }

            Integer atIndex = email.lastIndexOf('@');
            // Skip emails without '@' or without anything after the '@'.
            if (atIndex < 0 || atIndex == email.length() - 1) {
                continue;
            }

            String domain = email.substring(atIndex + 1).toLowerCase();

            if (!domainToContacts.containsKey(domain)) {
                domainToContacts.put(domain, new List<Contact>());
            }
            domainToContacts.get(domain).add(
                new Contact(Id = c.Id, Email = c.Email, AccountId = c.AccountId)
            );
        }

        return domainToContacts;
    }
}
