/**
 * @description Record-search service backing the admin "record finder" Lightning component.
 *
 * Runs a single dynamic SOQL query against an arbitrary object with simple equality
 * filters. All object/field names are resolved (and normalized) through Schema describe
 * information, so names can never inject SOQL; all filter values are converted to safe
 * literals. The query executes in user mode, which enforces record sharing, object
 * permissions and field-level security for the running user.
 *
 * All validation failures are surfaced as RecordSearchService.SearchException.
 *
 * @author   Salesforce Engineering
 * @since    API version 67.0
 */
public inherited sharing class RecordSearchService {

    /** Minimum allowed value for maxRows. */
    private static final Integer MIN_ROWS = 1;
    /** Maximum allowed value for maxRows. */
    private static final Integer MAX_ROWS = 200;

    /**
     * @description Thrown for every invalid input, permission problem or query failure
     *              raised by this service. Never lets any other exception type escape.
     */
    public class SearchException extends Exception {}

    /**
     * @description Searches an object using simple equality filters.
     *
     * @param objectApiName API name of the object to query (case-insensitive).
     * @param fields        Field API names to select in addition to Id (case-insensitive).
     * @param filters       Map of field API name to filter value (equality, ANDed together).
     *                      Values may be String, Boolean, Date, Datetime, Decimal, Integer,
     *                      Long, Double, Id or null. May be null or empty for no filtering.
     * @param orderByField  Field API name to sort by ascending; ignored when null/blank.
     * @param maxRows       Row limit; must be between 1 and 200 inclusive.
     * @return Matching records; never null.
     * @throws SearchException if the object does not exist, fields is null/empty, any field
     *         name (selected, filter or order-by) is not a field of the object, a filter
     *         field is not filterable, the order-by field is not sortable, the running user
     *         lacks read access to the object or any involved field, maxRows is out of
     *         range, or the query itself fails.
     */
    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // ------------------------------------------------------------------
        // 1. Validate maxRows.
        // ------------------------------------------------------------------
        if (maxRows == null || maxRows < MIN_ROWS || maxRows > MAX_ROWS) {
            throw new SearchException(
                'maxRows must be a whole number between ' + MIN_ROWS + ' and ' + MAX_ROWS + '.'
            );
        }

        // ------------------------------------------------------------------
        // 2. Validate the requested field list.
        // ------------------------------------------------------------------
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('fields must not be null or empty.');
        }

        // ------------------------------------------------------------------
        // 3. Resolve and validate the object (lookup is case-insensitive).
        // ------------------------------------------------------------------
        Schema.SObjectType sobjType =
            (objectApiName == null) ? null : Schema.getGlobalDescribe().get(objectApiName);

        if (sobjType == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }

        Schema.DescribeSObjectResult objDesc = sobjType.getDescribe();

        // Object-level read (CRUD) check for the running user.
        if (!objDesc.isAccessible()) {
            throw new SearchException(
                'The running user does not have read access to object: ' + objDesc.getName()
            );
        }

        // keys of fields.getMap() are matched case-insensitively.
        Map<String, Schema.SObjectField> fieldMap = objDesc.fields.getMap();

        // ------------------------------------------------------------------
        // 4. Resolve and validate the SELECT fields.
        //    Only canonical names returned by describe are used in the query
        //    string, so raw user input never reaches the SOQL text.
        // ------------------------------------------------------------------
        List<String> selectFields = new List<String>{ 'Id' };
        Set<String> seenFields = new Set<String>();

        for (String fieldName : fields) {
            if (String.isBlank(fieldName)) {
                throw new SearchException('Field names in fields must not be blank.');
            }

            Schema.SObjectField fieldToken = fieldMap.get(fieldName);
            if (fieldToken == null) {
                throw new SearchException(
                    'Not a field of ' + objDesc.getName() + ': ' + fieldName
                );
            }

            Schema.DescribeFieldResult fieldDesc = fieldToken.getDescribe();

            // Field-level security check for the running user.
            if (!fieldDesc.isAccessible()) {
                throw new SearchException(
                    'The running user does not have read access to field: ' + fieldDesc.getName()
                );
            }

            String canonical = fieldDesc.getName().toLowerCase();
            // Id is always selected; skip duplicates (case-insensitive).
            if (canonical != 'id' && !seenFields.contains(canonical)) {
                seenFields.add(canonical);
                selectFields.add(fieldDesc.getName());
            }
        }

        // ------------------------------------------------------------------
        // 5. Resolve and validate the filter fields and build the WHERE clause.
        // ------------------------------------------------------------------
        List<String> conditions = new List<String>();

        if (filters != null && !filters.isEmpty()) {
            for (String filterField : filters.keySet()) {
                if (String.isBlank(filterField)) {
                    throw new SearchException('Filter field names must not be blank.');
                }

                Schema.SObjectField fieldToken = fieldMap.get(filterField);
                if (fieldToken == null) {
                    throw new SearchException(
                        'Filter field is not a field of ' + objDesc.getName() + ': ' + filterField
                    );
                }

                Schema.DescribeFieldResult fieldDesc = fieldToken.getDescribe();

                if (!fieldDesc.isFilterable()) {
                    throw new SearchException(
                        'Field cannot be used in a WHERE clause: ' + fieldDesc.getName()
                    );
                }

                if (!fieldDesc.isAccessible()) {
                    throw new SearchException(
                        'The running user does not have read access to filter field: '
                            + fieldDesc.getName()
                    );
                }

                conditions.add(
                    fieldDesc.getName() + ' = ' + toSoqlLiteral(filters.get(filterField))
                );
            }
        }

        // ------------------------------------------------------------------
        // 6. Resolve and validate the order-by field.
        // ------------------------------------------------------------------
        String orderByClause = '';

        if (String.isNotBlank(orderByField)) {
            Schema.SObjectField fieldToken = fieldMap.get(orderByField);
            if (fieldToken == null) {
                throw new SearchException(
                    'orderByField is not a field of ' + objDesc.getName() + ': ' + orderByField
                );
            }

            Schema.DescribeFieldResult fieldDesc = fieldToken.getDescribe();

            if (!fieldDesc.isSortable()) {
                throw new SearchException(
                    'Field cannot be used in an ORDER BY clause: ' + fieldDesc.getName()
                );
            }

            if (!fieldDesc.isAccessible()) {
                throw new SearchException(
                    'The running user does not have read access to order-by field: '
                        + fieldDesc.getName()
                );
            }

            orderByClause = ' ORDER BY ' + fieldDesc.getName() + ' ASC';
        }

        // ------------------------------------------------------------------
        // 7. Assemble and run the single query in user mode, which enforces
        //    record sharing, object permissions and field-level security
        //    regardless of the sharing context of the caller.
        // ------------------------------------------------------------------
        String soql = 'SELECT ' + String.join(selectFields, ', ')
            + ' FROM ' + objDesc.getName();

        if (!conditions.isEmpty()) {
            soql += ' WHERE ' + String.join(conditions, ' AND ');
        }

        soql += orderByClause;
        soql += ' LIMIT ' + maxRows;

        try {
            return Database.query(soql, AccessLevel.USER_MODE);
        } catch (QueryException qe) {
            // Covers malformed literals (e.g. invalid Id/date strings from the UI)
            // and any other query-time failure. Only SearchException escapes.
            throw new SearchException('Query failed: ' + qe.getMessage());
        }
    }

    /**
     * @description Converts a raw filter value of any supported type into a safe SOQL
     *              literal. Strings are escaped with String.escapeSingleQuotes to prevent
     *              SOQL injection; unsupported types are rejected.
     *
     * @param value The filter value (String, Boolean, Date, Datetime, Decimal, Integer,
     *              Long, Double, Id or null).
     * @return A SOQL-safe literal.
     * @throws SearchException if the value type is not supported.
     */
    private static String toSoqlLiteral(Object value) {
        if (value == null) {
            return 'null';
        }
        if (value instanceof String) {
            return '\'' + String.escapeSingleQuotes((String) value) + '\'';
        }
        if (value instanceof Id) {
            // Id values are always well-formed by construction.
            return '\'' + String.valueOf((Id) value) + '\'';
        }
        if (value instanceof Boolean) {
            return String.valueOf((Boolean) value);
        }
        if (value instanceof Date) {
            return String.valueOf((Date) value);
        }
        if (value instanceof Datetime) {
            return String.valueOf((Datetime) value);
        }
        if (value instanceof Decimal) {
            // Also covers Integer/Long/Double values, which convert to Decimal.
            return String.valueOf((Decimal) value);
        }
        if (value instanceof Integer) {
            return String.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return String.valueOf((Long) value);
        }
        if (value instanceof Double) {
            return String.valueOf((Double) value);
        }
        throw new SearchException(
            'Filter value has an unsupported type: '
                + (value instanceof SObject ? String.valueOf(value) : String.valueOf(value))
        );
    }
