/**
 * Invocable Apex action for Flow: finds an existing Contact by email.
 *
 * - Accepts a batch of requests (up to 200 per Flow bulkification limits).
 * - Matching is case-insensitive and ignores leading/trailing whitespace.
 * - Blank/null input emails or unmatched emails yield found=false, contactId=null.
 * - When multiple contacts share an email, the earliest-created contact wins.
 * - Uses at most one SOQL query per invocation.
 * - Declared "with sharing" so results respect the running user's record access.
 */
public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(required=true label='Email' description='Email address of the contact to look up.')
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id' description='Id of the matching contact, or null if not found.')
        public Id contactId;

        @InvocableVariable(label='Found' description='True if a contact with the given email exists and is visible to the running user.')
        public Boolean found;
    }

    @InvocableMethod(
        label='Find Contact by Email'
        description='Looks up an existing contact by email address. Matching is case-insensitive, ignores surrounding whitespace, and returns the earliest-created contact when duplicates exist. Returns one result per request, in the same order.'
    )
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        // Normalize all non-blank input emails into a distinct set of lookup keys.
        Set<String> normalizedEmails = new Set<String>();
        for (Request request : requests) {
            String normalized = normalizeEmail(request);
            if (normalized != null) {
                normalizedEmails.add(normalized);
            }
        }

        // Single SOQL query for the entire batch. Order by CreatedDate (then Id as a
        // deterministic tiebreaker) so the first hit per email is the earliest contact.
        // SOQL email comparisons are case-insensitive, and the Email IN bind variable
        // is parameterized, so the query is injection-safe.
        Map<String, Id> contactIdByEmail = new Map<String, Id>();
        if (!normalizedEmails.isEmpty()) {
            for (Contact contact : [
                SELECT Id, Email
                FROM Contact
                WHERE Email IN :normalizedEmails
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String key = normalizeStoredEmail(contact.Email);
                if (key != null && !contactIdByEmail.containsKey(key)) {
                    contactIdByEmail.put(key, contact.Id);
                }
            }
        }

        // Build exactly one Result per Request, preserving the original order.
        for (Request request : requests) {
            Result result = new Result();
            result.found = false;
            result.contactId = null;

            String normalized = normalizeEmail(request);
            if (normalized != null && contactIdByEmail.containsKey(normalized)) {
                result.contactId = contactIdByEmail.get(normalized);
                result.found = true;
            }

            results.add(result);
        }

        return results;
    }

    /**
     * Normalizes a request email: trims whitespace, lowercases for
     * case-insensitive comparison. Returns null for null/blank input.
     */
    private static String normalizeEmail(Request request) {
        if (request == null || request.email == null) {
            return null;
        }
        String trimmed = request.email.trim();
        if (trimmed.isEmpty()) {
            return null;
        }
        return trimmed.toLowerCase();
    }

    /**
     * Normalizes a Contact's stored Email value the same way, so keys from the
     * query always match keys built from the requests, regardless of case or
     * surrounding whitespace stored on the record.
     */
    private static String normalizeStoredEmail(String email) {
        if (email == null) {
            return null;
        }
        String trimmed = email.trim();
        if (trimmed.isEmpty()) {
            return null;
        }
        return trimmed.toLowerCase();
    }
}
