/**
 * Parses e-commerce order JSON payloads posted to an Apex REST endpoint and
 * builds acknowledgement responses.
 */
public inherited sharing class OrderPayloadParser {

    /** Thrown for any malformed or invalid payload. */
    public class PayloadException extends Exception {}

    /** One order line. */
    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    /** Parsed order. */
    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    /**
     * Parses a JSON order payload.
     *
     * @param body the raw JSON request body
     * @return the parsed Order
     * @throws OrderPayloadParser.PayloadException when the body is null/blank,
     *         not valid JSON, not a JSON object, has a missing or blank
     *         "number", or contains a line with a missing "sku", a missing or
     *         non-positive "quantity", or a missing or negative "unitPrice"
     */
    public static Order parse(String body) {
        if (body == null || body.trim() == '') {
            throw new PayloadException('Request body is null or blank');
        }

        Object root;
        try {
            root = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Body is not valid JSON: ' + e.getMessage());
        }

        if (!(root instanceof Map<String, Object>)) {
            throw new PayloadException('Body is not a JSON object');
        }
        Map<String, Object> payload = (Map<String, Object>) root;

        // --- order number (required, non-blank) ---
        Object numberObj = payload.get('number');
        if (numberObj == null) {
            throw new PayloadException('Missing required field "number"');
        }
        String orderNumber = (numberObj instanceof String)
            ? (String) numberObj
            : String.valueOf(numberObj);
        if (orderNumber == null || orderNumber.trim() == '') {
            throw new PayloadException('Field "number" is blank');
        }

        Order order = new Order();
        order.orderNumber = orderNumber;

        // --- optional date (ISO yyyy-MM-dd) ---
        Object dateObj = payload.get('date');
        if (dateObj instanceof String) {
            try {
                order.orderDate = Date.valueOf((String) dateObj);
            } catch (Exception e) {
                order.orderDate = null;
            }
        }

        // --- optional currency ---
        Object currencyObj = payload.get('currency');
        if (currencyObj instanceof String) {
            order.currencyCode = (String) currencyObj;
        }

        // --- optional customer.email ---
        Object customerObj = payload.get('customer');
        if (customerObj instanceof Map<String, Object>) {
            Object emailObj = ((Map<String, Object>) customerObj).get('email');
            if (emailObj instanceof String) {
                order.customerEmail = (String) emailObj;
            }
        }

        // --- lines (optional; empty when missing/null) ---
        order.lines = new List<Line>();
        order.total = 0;

        Object linesObj = payload.get('lines');
        if (linesObj != null) {
            if (!(linesObj instanceof List<Object>)) {
                throw new PayloadException('Field "lines" is not a JSON array');
            }
            for (Object lineObj : (List<Object>) linesObj) {
                if (!(lineObj instanceof Map<String, Object>)) {
                    throw new PayloadException('Line is not a JSON object');
                }
                Map<String, Object> lineMap = (Map<String, Object>) lineObj;

                // sku: required
                Object skuObj = lineMap.get('sku');
                if (skuObj == null) {
                    throw new PayloadException('Line is missing required field "sku"');
                }
                String sku = (skuObj instanceof String)
                    ? (String) skuObj
                    : String.valueOf(skuObj);

                // quantity: required and positive
                Object qtyObj = lineMap.get('quantity');
                Decimal quantityDec = toDecimal(qtyObj);
                if (qtyObj == null || quantityDec == null || quantityDec <= 0) {
                    throw new PayloadException(
                        'Line "' + sku + '" has a missing or non-positive "quantity"');
                }

                // unitPrice: required and non-negative
                Object priceObj = lineMap.get('unitPrice');
                Decimal unitPrice = toDecimal(priceObj);
                if (priceObj == null || unitPrice == null || unitPrice < 0) {
                    throw new PayloadException(
                        'Line "' + sku + '" has a missing or negative "unitPrice"');
                }

                // discount: optional, defaults to 0
                Decimal discount = 0;
                Object discountObj = lineMap.get('discount');
                if (discountObj != null) {
                    Decimal parsedDiscount = toDecimal(discountObj);
                    if (parsedDiscount != null) {
                        discount = parsedDiscount;
                    }
                }

                Line line = new Line();
                line.sku = sku;
                line.quantity = quantityDec.intValue();
                line.unitPrice = unitPrice;
                line.discount = discount;
                // Rounded to 2 decimal places, ties rounded half up.
                line.lineTotal = (quantityDec * unitPrice * (1 - discount)).setScale(2);

                order.lines.add(line);
                order.total += line.lineTotal;
            }
        }

        return order;
    }

    /**
     * Builds the acknowledgement JSON for a parsed order.
     *
     * @param order the parsed order
     * @return a JSON object with keys "number", "status", "lineCount" and "total"
     */
    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order == null ? null : order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', (order == null || order.lines == null) ? 0 : order.lines.size());
        ack.put('total', (order == null || order.total == null) ? 0 : order.total);
        return JSON.serialize(ack);
    }

    /** Safely converts an untyped JSON value to a Decimal, or null if not numeric. */
    private static Decimal toDecimal(Object value) {
        if (value instanceof Decimal) {
            return (Decimal) value;
        }
        if (value instanceof Integer) {
            return Decimal.valueOf((Integer) value);
        }
        if (value instanceof Long) {
            return Decimal.valueOf((Long) value);
        }
        return null;
    }
}
