@isTest
private class AddressVerificationServiceTest {
    private static final String EXPECTED_ENDPOINT = 'callout:FB_Address_API/v2/verify';

    // ---------------------------------------------------------------------
    // Mock implementations
    // ---------------------------------------------------------------------

    /**
     * Mock that returns a configurable HTTP status code and body, and records
     * the outgoing request so tests can assert the exact API contract.
     */
    private class RecordingMock implements HttpCalloutMock {
        private Integer statusCode;
        private String body;

        // Captured state, inspectable by the test after the callout.
        public HttpRequest capturedRequest;
        public Integer callCount = 0;

        public RecordingMock(Integer statusCode, String body) {
            this.statusCode = statusCode;
            this.body = body;
        }

        public HttpResponse respond(HttpRequest req) {
            callCount++;
            capturedRequest = req;
            HttpResponse res = new HttpResponse();
            res.setStatusCode(statusCode);
            res.setBody(body);
            res.setHeader('Content-Type', 'application/json');
            return res;
        }
    }

    /**
     * Mock that fails the test if any callout is attempted.
     */
    private class FailIfCalledMock implements HttpCalloutMock {
        public Integer callCount = 0;

        public HttpResponse respond(HttpRequest req) {
            callCount++;
            throw new AddressVerificationService.AddressVerificationException(
                'No callout should be made, but one was attempted to: '
                + req.getEndpoint()
            );
        }
    }

