        return '{"status":"CORRECTED","address":{"street":"999 Corrected Ave",'
            + '"city":"New Town","postalCode":"99999","country":"Canada"}}';
    }

    private static String invalidBody() {
        return '{"status":"INVALID","address":{"street":"1 Nowhere Rd",'
            + '"city":"Nowhere","postalCode":"00000","country":"X"}}';
    }

