/**
 * Tests for ShippingCostCalculator.
 *
 * Covers the documented contract:
 *  - weight validation (null, zero, negative -> ShippingException)
 *  - base price tiers and their exact boundaries (1 / 5 / 20 kg, "up to and including")
 *  - surcharge above 20 kg for every started kilogram (ceiling behaviour)
 *  - zone lookup, case-insensitivity, unknown/null zone -> ShippingException
 *  - express surcharge (+50%), null express = standard
 *  - free shipping rule (DOMESTIC, standard, orderValue >= 100)
 *  - final rounding to 2 decimals, HALF_UP
 *
 * Self-contained: no org data is read or created (SeeAllData is not used).
 */
@IsTest
private class ShippingCostCalculatorTest {

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    // Decimal-safe equality (value based, ignores scale differences).
    private static void assertPrice(Decimal expected, Decimal actual, String context) {
        Assert.isTrue(
            expected != null && actual != null && expected.compareTo(actual) == 0,
            context + ': expected ' + expected + ' but was ' + actual
        );
    }

    private static Decimal quote(Decimal weightKg, String zone, Boolean express, Decimal orderValue) {
        return ShippingCostCalculator.quote(weightKg, zone, express, orderValue);
    }

    // Asserts that exactly a ShippingException is thrown (any other exception
    // propagates and fails the test).
    private static void assertThrowsShippingException(
        Decimal weightKg,
        String zone,
        Boolean express,
        Decimal orderValue,
        String context
    ) {
        ShippingCostCalculator.ShippingException thrown;
        try {
            quote(weightKg, zone, express, orderValue);
        } catch (ShippingCostCalculator.ShippingException e) {
            thrown = e;
        }
        Assert.isInstanceOf(
            thrown,
            ShippingCostCalculator.ShippingException.class,
            context + ': expected ShippingException but was ' + thrown
        );
    }

    // ---------------------------------------------------------------------
    // Weight validation
    // ---------------------------------------------------------------------

    @IsTest
    static void weightMustBeGreaterThanZero() {
        assertThrowsShippingException(null, 'DOMESTIC', false, null, 'null weight');
        assertThrowsShippingException(0, 'DOMESTIC', false, null, 'zero weight');
        assertThrowsShippingException(-0.01, 'DOMESTIC', false, null, 'slightly negative weight');
        assertThrowsShippingException(-5, 'EU', true, 50, 'clearly negative weight');
        // Smallest positive weight is still valid and falls into the first tier.
        assertPrice(5.00, quote(0.01, 'DOMESTIC', false, null), 'smallest positive weight');
        assertPrice(5.00, quote(0.5, 'DOMESTIC', false, null), 'fractional weight below 1 kg');
    }

    // ---------------------------------------------------------------------
    // Base price tiers and exact boundaries ("up to and including")
    // ---------------------------------------------------------------------

    @IsTest
    static void basePriceTierBoundaries() {
        // Up to and including 1 kg -> 5.00
        assertPrice(5.00, quote(1, 'DOMESTIC', false, null), 'exactly 1 kg is first tier');
        assertPrice(5.00, quote(0.99, 'DOMESTIC', false, null), 'just below 1 kg');

        // Above 1 kg, up to and including 5 kg -> 9.50
        assertPrice(9.50, quote(1.01, 'DOMESTIC', false, null), 'just above 1 kg is second tier');
        assertPrice(9.50, quote(2, 'DOMESTIC', false, null), 'middle of second tier');
        assertPrice(9.50, quote(5, 'DOMESTIC', false, null), 'exactly 5 kg is second tier');

        // Above 5 kg, up to and including 20 kg -> 18.00
        assertPrice(18.00, quote(5.01, 'DOMESTIC', false, null), 'just above 5 kg is third tier');
        assertPrice(18.00, quote(10, 'DOMESTIC', false, null), 'middle of third tier');
        assertPrice(18.00, quote(20, 'DOMESTIC', false, null), 'exactly 20 kg is third tier');
    }

    // ---------------------------------------------------------------------
    // Surcharge above 20 kg: 18.00 + 0.75 per STARTED kilogram above 20
    // ---------------------------------------------------------------------

    @IsTest
    static void surchargeAboveTwentyKilograms() {
        // Any fraction above 20 starts a new kilogram (ceiling behaviour).
        assertPrice(18.75, quote(20.01, 'DOMESTIC', false, null), '20.01 kg: one started kg');
        assertPrice(18.75, quote(20.1, 'DOMESTIC', false, null), '20.1 kg documented example');
        assertPrice(18.75, quote(20.5, 'DOMESTIC', false, null), '20.5 kg: still one started kg');
        assertPrice(18.75, quote(20.99, 'DOMESTIC', false, null), '20.99 kg: still one started kg');
        assertPrice(18.75, quote(21, 'DOMESTIC', false, null), '21 kg: one started kg');
        assertPrice(19.50, quote(22, 'DOMESTIC', false, null), '22 kg documented example');
        assertPrice(20.25, quote(22.1, 'DOMESTIC', false, null), '22.1 kg: three started kg');
        assertPrice(25.50, quote(30, 'DOMESTIC', false, null), '30 kg: ten started kg');
    }

    // ---------------------------------------------------------------------
    // Zones: case-insensitive lookup, unknown/null zone throws
    // ---------------------------------------------------------------------

    @IsTest
    static void zoneLookupIsCaseInsensitive() {
