/**
 * Utility to read the active picklist / multi-select picklist values of any
 * object's picklist field, chosen at runtime, in field-definition order.
 */
public with sharing class PicklistService {

    /**
     * A single picklist option exposed to callers.
     */
    public class Option {

        /** The picklist API value (e.g. `In_Progress`). */
        public String value;

        /** The user-facing label (e.g. `In Progress`). Falls back to the API
            value when the entry has no distinct label. */
        public String label;

        /** True only for the field's default value. */
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    /**
     * Thrown for invalid input, unknown objects/fields, or non-picklist fields.
     */
    public class PicklistServiceException extends Exception {}

    /**
     * Returns the active values of the given picklist or multi-select picklist
     * field, in the order they are defined on the field.
     *
     * @param  objectApiName  object API name, case-insensitive (e.g. `account`,
     *                        `FB_Asset_Check__c`)
     * @param  fieldApiName   field API name, case-insensitive (e.g. `INDUSTRY`,
     *                        `Status__c`)
     * @return list of active options; empty list if the field has no active values
     * @throws PicklistServiceException if either name is null/blank, the object
     *         does not exist, the field does not exist on the object, or the
     *         field is not a picklist / multi-select picklist
     */
    public static List<Option> activeOptions(String objectApiName, String fieldApiName) {
        // --- Validate input ---------------------------------------------------
        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name must not be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name must not be null or blank.');
        }

        String objName = objectApiName.trim();
        String fldName = fieldApiName.trim();

        // --- Resolve the object (global describe keys are case-insensitive) ---
        Schema.SObjectType sObjectType;
        try {
            sObjectType = Schema.getGlobalDescribe().get(objName);
        } catch (Exception e) {
            throw new PicklistServiceException(
                'Unable to resolve object "' + objName + '": ' + e.getMessage());
        }
        if (sObjectType == null) {
            throw new PicklistServiceException('Object "' + objName + '" does not exist.');
        }

        Schema.DescribeSObjectResult objectDescribe;
        try {
            objectDescribe = sObjectType.getDescribe();
        } catch (Exception e) {
            throw new PicklistServiceException(
                'Unable to describe object "' + objName + '": ' + e.getMessage());
        }

        // --- Resolve the field (describe field map keys are case-insensitive) -
        Map<String, Schema.SObjectField> fieldMap = objectDescribe.fields.getMap();
        Schema.SObjectField sObjectField = fieldMap.get(fldName);
        if (sObjectField == null) {
            throw new PicklistServiceException(
                'Field "' + fldName + '" does not exist on object "' + objName + '".');
        }

        Schema.DescribeFieldResult fieldDescribe;
        try {
            fieldDescribe = sObjectField.getDescribe();
        } catch (Exception e) {
            throw new PicklistServiceException(
                'Unable to describe field "' + objName + '.' + fldName + '": ' + e.getMessage());
        }

        // --- Ensure it is a picklist or multi-select picklist -----------------
        Schema.DisplayType fieldType = fieldDescribe.getType();
        if (fieldType != Schema.DisplayType.PICKLIST
                && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field "' + objName + '.' + fldName + '" is not a picklist or multi-select picklist.');
        }

        // --- Collect active entries in definition order -----------------------
        List<Schema.PicklistEntry> entries;
        try {
            // getPicklistValues() returns entries in field-definition order,
            // including inactive ones; we filter to active entries below.
            entries = fieldDescribe.getPicklistValues();
        } catch (Exception e) {
            throw new PicklistServiceException(
                'Unable to read picklist values for "' + objName + '.' + fldName + '": '
                + e.getMessage());
        }

        List<Option> options = new List<Option>();
        Boolean defaultFound = false;

        for (Schema.PicklistEntry entry : entries) {
            if (entry.isActive()) {
                Boolean isDefault = false;
                if (!defaultFound && entry.isDefaultValue()) {
                    isDefault = true;
                    defaultFound = true;
                }
                String label = entry.getLabel();
                if (String.isBlank(label)) {
                    label = entry.getValue();
                }
                options.add(new Option(entry.getValue(), label, isDefault));
            }
        }

        return options;
    }
}
