/**
 * Queueable job that re-rates up to 50,000 Accounts from their AnnualRevenue,
 * 200 Accounts per execution, chaining to the next job until the full list
 * has been processed.
 *
 * Rating rules:
 *   AnnualRevenue >= 1,000,000  -> 'Hot'
 *   AnnualRevenue >= 100,000    -> 'Warm'
 *   otherwise (incl. null)      -> 'Cold'
 *
 * Start with AccountScoringJob.start(accountIds). After Test.startTest() /
 * Test.stopTest() in a test, the entire chain runs synchronously, so any list
 * up to 50,000 Ids is fully rated in one test.
 */
public inherited sharing class AccountScoringJob implements Queueable {

    private static final Integer BATCH_SIZE = 200;

    @TestVisible
    private List<Id> accountIds;

    /** @param accountIds full (or remaining) list of Account Ids to rate */
    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds == null) ? new List<Id>() : accountIds;
    }

    /**
     * Processes the first 200 Ids of the list, then chains a new job for the rest.
     * Safe to call directly (e.g. execute(null) in tests): QueueableContext is not used.
     */
    public void execute(QueueableContext context) {
        Integer size = Math.min(BATCH_SIZE, accountIds.size());

        List<Id> batchIds = new List<Id>(size);
        for (Integer i = 0; i < size; i++) {
            batchIds.add(accountIds[i]);
        }

        // Exactly one SOQL query per execution.
        List<Account> accounts = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
        ];

        for (Account acc : accounts) {
            acc.Rating = computeRating(acc.AnnualRevenue);
        }

        // Exactly one DML statement per execution.
        if (!accounts.isEmpty()) {
            update accounts;
        }

        // Enqueue the next link in the chain if any Ids remain. This is done
        // unconditionally, including in test context, so the whole chain is
        // executed (synchronously) by Test.stopTest().
        if (size < accountIds.size()) {
            List<Id> remaining = new List<Id>(accountIds.size() - size);
            for (Integer i = size; i < accountIds.size(); i++) {
                remaining.add(accountIds[i]);
            }
            System.enqueueJob(new AccountScoringJob(remaining));
        }
    }

    private static String computeRating(Decimal annualRevenue) {
        if (annualRevenue == null) {
            return 'Cold';
        }
        if (annualRevenue >= 1000000) {
            return 'Hot';
        }
        if (annualRevenue >= 100000) {
            return 'Warm';
        }
        return 'Cold';
    }

    /**
     * Enqueues the first job of the chain.
     * @return the AsyncApexJob Id of the first job, or null when accountIds
     *         is null or empty (nothing is enqueued in that case).
     */
    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }
}
