public inherited sharing class ErpAccountSyncJob implements Queueable {

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpAccountSyncJob(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(QueueableContext context) {
        // Attach the finalizer before doing any work so that the outcome of
        // this transaction is always logged (and failed runs retried).
        System.attachFinalizer(new ErpSyncFinalizer(accountIds, attempt));

        List<Account> accounts = [
            SELECT Id
            FROM Account
            WHERE Id IN :accountIds
        ];

        for (Account acc : accounts) {
            acc.Description = 'Synced to ERP';
        }

        // DML statements are all-or-nothing: if any account cannot be saved,
        // a DmlException is thrown and none of the changes are committed.
        // The exception is deliberately not caught so the job (and this
        // transaction) fails, triggering the finalizer's failure handling.
        update accounts;
    }
}
