public inherited sharing class ErpSyncFinalizer implements Finalizer {

    private static final Integer MAX_ATTEMPTS = 3;

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(FinalizerContext context) {
        Exception err = context.getException();

        FB_Job_Log__c log = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Status__c = (err == null) ? 'Success' : 'Failed',
            Attempt__c = attempt
        );

        if (err != null) {
            log.Error__c = truncate(err.getMessage());

            // Retry the same work with an incremented attempt number,
            // but never go past the third attempt.
            if (attempt < MAX_ATTEMPTS) {
                System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
            }
        }

        insert log;
    }

    private static String truncate(String value) {
        if (value == null) {
            return null;
        }
        return value.length() > 255 ? value.substring(0, 255) : value;
    }
}
