trigger OpportunityTrigger on Opportunity (after insert, after update, after delete, after undelete) {
    // Delegate all logic to the handler. Handler runs after-record logic so the
    // database always reflects the outcome of the current DML statement before we
    // recalculate, which keeps totals correct across multiple DML statements in
    // the same transaction (Flow + Apex, tests, etc.).
    if (Trigger.isAfter && Trigger.isInsert) {
        OpportunityPipelineHandler.afterInsert(Trigger.new);
    } else if (Trigger.isAfter && Trigger.isUpdate) {
        OpportunityPipelineHandler.afterUpdate(Trigger.new, Trigger.old);
    } else if (Trigger.isAfter && Trigger.isDelete) {
        OpportunityPipelineHandler.afterDelete(Trigger.old);
    } else if (Trigger.isAfter && Trigger.isUndelete) {
        OpportunityPipelineHandler.afterUndelete(Trigger.new);
    }
}
