/**
 * @description Scheduled job that purges old FB_Integration_Log__c records.
 *
 * Retention rules:
 *   - Any log older than 30 days is deleted, EXCEPT logs whose Level__c is 'ERROR'.
 *   - 'ERROR' logs are deleted only once they are older than 180 days.
 *   - Logs with a blank Level__c are treated like non-error logs (30-day retention).
 *
 * Because the volume of logs can be large, the Schedulable execute() method
 * delegates the actual deletion to a batch job (this class also implements
 * Database.Batchable), so we never risk hitting governor limits on delete/DML.
 */
public inherited sharing class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {

    @TestVisible
    private static final Integer RETENTION_DAYS_STANDARD = 30;

    @TestVisible
    private static final Integer RETENTION_DAYS_ERROR = 180;

    /** Batch size for the delete job. */
    @TestVisible
    private static final Integer BATCH_SIZE = 10000;

    /** No-argument constructor (required by the scheduling contract). */
    public LogPurgeJob() {}

    /**
     * @description Schedulable entry point. Kicks off the batch delete so the
     *              purge is bulk-safe regardless of log volume.
     * @param ctx Scheduling context provided by the platform.
     */
    public void execute(SchedulableContext ctx) {
        Database.executeBatch(new LogPurgeJob(), BATCH_SIZE);
    }

    /**
     * @description Returns the logs eligible for deletion:
     *              older than 30 days and not ERROR, or older than 180 days
     *              regardless of level.
     */
    public Database.QueryLocator start(Database.BatchableContext bc) {
        Datetime standardCutoff = Datetime.now().addDays(-RETENTION_DAYS_STANDARD);
        Datetime errorCutoff = Datetime.now().addDays(-RETENTION_DAYS_ERROR);

        // SOQL: "Level__c != 'ERROR'" does not match records where Level__c is
        // null, so blank-level logs must be selected explicitly.
        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (CreatedDate < :standardCutoff AND (Level__c != 'ERROR' OR Level__c = null))
               OR (CreatedDate < :errorCutoff AND Level__c = 'ERROR')
        ]);
    }

    /**
     * @description Deletes the batch of eligible log records. Partial success is
     *              allowed so one bad row never aborts the whole purge.
     */
    public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
        List<Id> idsToDelete = new List<Id>();
        for (FB_Integration_Log__c logRecord : scope) {
            idsToDelete.add(logRecord.Id);
        }
        Database.delete(idsToDelete, false);
    }

    /**
     * @description Batch completion hook. Nothing to do; recurring runs are
     *              handled by the nightly cron entry created in scheduleNightly().
     */
    public void finish(Database.BatchableContext bc) {}

    /**
     * @description Schedules this job to run every day at 02:00 under the job
     *              name 'Log purge (nightly)'.
     * @return The Id of the CronTrigger record created by System.schedule.
     */
    public static Id scheduleNightly() {
        // Seconds Minutes Hours DayOfMonth Month DayOfWeek (runs daily at 02:00).
        String cronExpression = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }
}
