public inherited sharing class Opportunities extends fflib_SObjectDomain
{
    private static final String WON_STAGE = 'Closed Won';

    public Opportunities(List<Opportunity> records)
    {
        super(records);
    }

    public Opportunities(List<Opportunity> records, fflib_SObjectDomain.IConstructable constructorContext)
    {
        super(records, constructorContext);
    }

    /**
     * An opportunity qualifies on insert when it is created directly as Closed Won.
     */
    public override void afterInsert()
    {
        Set<Id> wonOpportunityIds = new Set<Id>();

        for (Opportunity record : (List<Opportunity>) getRecords())
        {
            if (record.StageName == WON_STAGE)
            {
                wonOpportunityIds.add(record.Id);
            }
        }

        startFulfilment(wonOpportunityIds);
    }

    /**
     * An opportunity qualifies on update when its stage changes to Closed Won
     * from any other stage. Editing an already Closed Won opportunity does not
     * qualify again.
     */
    public override void afterUpdate()
    {
        Map<Id, Opportunity> oldRecords = (Map<Id, Opportunity>) Trigger.oldMap;
        Set<Id> wonOpportunityIds = new Set<Id>();

        for (Opportunity record : (List<Opportunity>) getRecords())
        {
            Opportunity oldRecord = oldRecords.get(record.Id);

            if (record.StageName == WON_STAGE
                && oldRecord != null
                && oldRecord.StageName != WON_STAGE)
            {
                wonOpportunityIds.add(record.Id);
            }
        }

        startFulfilment(wonOpportunityIds);
    }

    /**
     * Calls the fulfilment service at most once per trigger invocation and
     * only when at least one qualifying opportunity was processed in this
     * invocation. The service is resolved via the Application factory so
     * tests can substitute it with Application.Service.setMock.
     */
    private void startFulfilment(Set<Id> opportunityIds)
    {
        if (opportunityIds.isEmpty())
        {
            return;
        }

        IOpportunityFulfilmentService service =
            (IOpportunityFulfilmentService) Application.Service.newInstance(
                IOpportunityFulfilmentService.class
            );

        service.startFulfilment(opportunityIds);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjects)
        {
            return new Opportunities((List<Opportunity>) sObjects);
        }
    }
