```apex
public inherited sharing class Opportunities extends fflib_SObjectDomain
{
    private static final String STAGE_CLOSED_WON = 'Closed Won';

    public Opportunities(List<Opportunity> records)
    {
        super(records);
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjects)
        {
            return new Opportunities((List<Opportunity>) sObjects);
        }
    }

    public override void onValidate()
    {
        for (Opportunity record : (List<Opportunity>) records)
        {
            // Rule 1: on insert and on update, Amount must not be negative.
            // If Amount is not populated, it is either null on insert or unchanged on update,
            // in which case it cannot newly violate this rule.
            if (record.Amount != null && record.Amount < 0)
            {
                error('Amount cannot be negative.', record, Opportunity.Amount);
            }

            // Rule 2: on update, an opportunity that was already Closed Won before the update
            // cannot have its Amount changed. Closing an opportunity as won and changing its
            // Amount in the same update is allowed, because the *old* stage was not Closed Won.
            //
            // Only evaluate old-vs-new comparisons when running inside an update trigger
            // execution (fflib's triggerHandler invokes onValidate in the before update event),
            // where Trigger.oldMap is available without any SOQL.
            if (Trigger.isExecuting && Trigger.isUpdate)
            {
                Opportunity beforeUpdate = (Opportunity) Trigger.oldMap.get(record.Id);

                // Amount counts as changed only if it was actually populated on the record
                // being processed; on partial updates an unpopulated field means "unchanged".
                Boolean amountPopulated =
                    record.getPopulatedFieldsAsMap().containsKey('Amount');

                Boolean wasClosedWon =
                    record.Id != null &&
                    beforeUpdate != null &&
                    STAGE_CLOSED_WON.equals(beforeUpdate.StageName);

                Boolean amountChanged =
                    amountPopulated && record.Amount != beforeUpdate.Amount;

                if (wasClosedWon && amountChanged)
                {
                    error('Amount cannot change on a won opportunity.', record, Opportunity.Amount);
                }
            }
        }
    }
}
