    }

    /**
     * Returns the open opportunities of the given accounts, ordered by Amount
     * descending (opportunities without an Amount last), then by CloseDate
     * ascending, limited to maxRecords rows in a single query.
     *
     * The query is built from the selector's query factory so that the
     * selector's standard field list and its CRUD/FLS enforcement settings
     * keep applying.
     */
    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        // Guard against null/empty inputs to stay bulk-safe and avoid pointless queries
        if (accountIds == null || accountIds.isEmpty() || maxRecords == null || maxRecords <= 0) {
            return new List<Opportunity>();
        }

        fflib_QueryFactory queryFactory = newQueryFactory();

        // Add the parent account's Name in addition to the selector's standard fields.
        // fflib_QueryFactory.addField(String) supports relationship field paths and
        // enforces FLS on them as well.
        queryFactory.addField('Account.Name');

        // Only open opportunities of the given accounts
        queryFactory.setCondition('IsClosed = false AND AccountId IN :accountIds');

        // Highest Amount first, opportunities without an Amount after all the others,
        // equal amounts by earliest CloseDate first.
        queryFactory.setSortOrder('Amount DESC NULLS LAST, CloseDate ASC');

        queryFactory.setLimit(maxRecords);

        // Explicitly enforce that the running user can read Opportunity records
        queryFactory.assertIsAccessible();

        return (List<Opportunity>) Database.query(queryFactory.toSOQL());
    }
}
