     * Full constructor for testing and special cases; defaults to the settings
     * above when not overridden.
     */
    public AccountsSelector(
        Boolean includeFieldSetFields,
        Boolean enforceCRUD,
        Boolean enforceSharing,
        Boolean limitQuery,
        fflib_QuerySecurityMode querySecurityMode
    ) {
        super(includeFieldSetFields, enforceCRUD, enforceSharing, limitQuery, querySecurityMode);
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
    }

    /**
     * The fields of this field set are appended to every query produced by this
     * selector (because includeFieldSetFields is true). Fields added by admins
     * to Credit_Review are picked up dynamically, without code changes.
     */
    public List<Schema.FieldSet> getSObjectFieldSetList() {
        return new List<Schema.FieldSet>{
            Account.SObjectType.fieldSets.getMap().get('Credit_Review')
        };
    }

    /**
     * Select accounts by Id. Runs WITH USER_MODE via the selector's data
     * access setting, so a user lacking read access to any selected field
     * gets an exception instead of data.
     *
     * @param accountIds the Account Ids to query
     * @return the matching Accounts, ordered by Id
     */
    public List<Account> selectById(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }
        return (List<Account>) selectSObjectsById(accountIds);
    }

    /**
     * Select accounts by Id together with their child Contacts in the same
     * query. The contact sub-select is built from ContactsSelector.getFieldList()
     * so it always reflects that selector's fields. WITH USER_MODE applies to
     * the whole query, including the subquery.
     *
     * @param accountIds the Account Ids to query
     * @return the matching Accounts with their Contacts child rows, ordered by Id
     */
    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Account>();
        }

        // Build the subquery from the existing ContactsSelector so it uses that
        // selector's field list.
        String contactSubQuery =
            '(select ' + new ContactsSelector().getFieldList() + ' from Contacts)';

        String query =
            'select ' + getFieldList() +
            ', ' + contactSubQuery +
            ' from ' + getSObjectName() +
            ' where Id in :accountIds' +
            getSecurityClause() +
            ' order by ' + getOrderBy();

        return (List<Account>) Database.query(query);
    }

    /**
     * Translates the selector's data access setting into the corresponding SOQL
     * security clause, so the platform enforces the running user's access.
     */
    private String getSecurityClause() {
        fflib_QuerySecurityMode securityMode = getQuerySecurityMode();
        if (securityMode == fflib_QuerySecurityMode.WITH_USER_MODE) {
            return ' with user_mode';
        }
        if (securityMode == fflib_QuerySecurityMode.WITH_SECURITY_ENFORCED) {
            return ' with security_enforced';
        }
        return '';
    }
