public inherited sharing class CaseEscalationService {

    public class EscalationException extends Exception {}

    public static void escalate(Set<Id> caseIds, String reason) {
        // Validate first: nothing may be read or written when the reason is blank.
        if (String.isBlank(reason)) {
            throw new EscalationException('An escalation reason is required.');
        }

        // Null or empty input: do nothing.
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);

        fflib_IUnitOfWork uow = Application.UnitOfWork.newInstance();

        Date tomorrow = Date.today().addDays(1);
        Boolean hasRecordsToCommit = false;

        for (Case caseRecord : cases) {
            // Skip closed cases and cases that are already escalated.
            if (caseRecord.Status == 'Closed' || caseRecord.IsEscalated == true) {
                continue;
            }

            Case escalatedCase = new Case(
                Id = caseRecord.Id,
                IsEscalated = true,
                Priority = 'High'
            );
            uow.registerDirty(escalatedCase);

            Task escalationTask = new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = caseRecord.Id,
                OwnerId = caseRecord.OwnerId,
                ActivityDate = tomorrow,
                Priority = 'High'
            );
            uow.registerNew(escalationTask);

            hasRecordsToCommit = true;
        }

        // Only commit when at least one case was escalated.
        if (hasRecordsToCommit) {
            uow.commitWork();
        }
    }
}
