```apex
/**
 * @description Service for creating onboarding Accounts together with their
 *              related Contacts in a single, atomic Unit of Work commit.
 *              All DML is delegated to fflib_SObjectUnitOfWork (Enterprise
 *              Patterns), so the service itself never issues DML directly.
 */
public without sharing class AccountOnboardingService
{
    /**
     * @description Creates one Account per map key and, for each entry in the
     *              key's list, one Contact with that LastName pointing at the
     *              new Account. Everything is inserted through a single
     *              fflib_SObjectUnitOfWork and committed once via commitWork().
     * @param       contactLastNamesByAccountName Map of Account Name to a list
     *              of Contact LastNames belonging to that Account.
     * @return      The newly inserted Accounts with their Ids populated;
     *              an empty list when the input map is null or empty.
     */
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName)
    {
        // Nothing to do: no DML, no records.
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty())
        {
            return new List<Account>();
        }

        // Single Unit of Work that knows about both involved SObject types.
        fflib_ISObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectType>
            {
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        List<Account> newAccounts = new List<Account>();

        // Register all Accounts for insertion first. The Unit of Work will
        // insert them in bulk, which keeps the commit bulk-safe.
        for (String accountName : contactLastNamesByAccountName.keySet())
        {
            Account newAccount = new Account(Name = accountName);
            newAccounts.add(newAccount);
            uow.registerNew(newAccount);
        }

        // Register the Contacts per Account. registerRelationship() defers the
        // AccountId population until the parent Accounts have been inserted by
        // commitWork(), so we never have to reference hardcoded Ids.
        for (Account newAccount : newAccounts)
        {
            List<String> lastNames = contactLastNamesByAccountName.get(newAccount.Name);

            if (lastNames == null || lastNames.isEmpty())
            {
                continue;
            }

            List<Contact> newContacts = new List<Contact>();
            for (String lastName : lastNames)
            {
                newContacts.add(new Contact(LastName = lastName));
            }

            if (!newContacts.isEmpty())
            {
                uow.registerRelationship(newAccount, Contact.AccountId, newContacts);
            }
        }

        // Single commit: inserts Accounts in bulk, inserts Contacts in bulk,
        // then sets Contact.AccountId. Ids are populated on the records we
        // hold in memory, so the returned Accounts carry their Ids.
        uow.commitWork();

        return newAccounts;
    }
}
