import { LightningElement, api } from 'lwc';
import { getRecord, getFieldValue } from 'lightning/uiRecordApi';

import NAME_FIELD from '@salesforce/schema/Account.Name';
import INDUSTRY_FIELD from '@salesforce/schema/Account.Industry';
import ANNUAL_REVENUE_FIELD from '@salesforce/schema/Account.AnnualRevenue';
import OWNER_NAME_FIELD from '@salesforce/schema/Account.Owner.Name';

const FIELDS = [NAME_FIELD, INDUSTRY_FIELD];
const OPTIONAL_FIELDS = [ANNUAL_REVENUE_FIELD, OWNER_NAME_FIELD];

export default class AccountHeader extends LightningElement {
    /**
     * Record page provides this. Because it is referenced as a reactive
     * template literal ('$recordId') in the wire adapter below, a change to
     * the property (e.g. a reused console tab) automatically triggers a
     * fresh getRecord call for the new record.
     */
    @api recordId;

    /** Wire results object: { data, error }. */
    account;

    @wire(getRecord, {
        recordId: '$recordId',
        fields: FIELDS,
        optionalFields: OPTIONAL_FIELDS
    })
    wiredAccount;

    get data() {
        return this.wiredAccount?.data;
    }

    get error() {
        return this.wiredAccount?.error;
    }

    /* ---- Render conditions ---- */

    /** No data and no error yet: show only the spinner. */
    get isLoading() {
        return !this.data && !this.error;
    }

    get hasRecord() {
        return !!this.data;
    }

    get hasError() {
        return !!this.error;
    }

    /* ---- Field values ---- */

    get accountName() {
        return getFieldValue(this.data, NAME_FIELD);
    }

    get industry() {
        return getFieldValue(this.data, INDUSTRY_FIELD);
    }

    get hasIndustry() {
        const industry = this.industry;
        return industry !== null && industry !== undefined && industry !== '';
    }

    get annualRevenue() {
        return getFieldValue(this.data, ANNUAL_REVENUE_FIELD);
    }

    get ownerName() {
        return getFieldValue(this.data, OWNER_NAME_FIELD);
    }

    get errorMessage() {
        return this.error?.body?.message;
    }
}
