import { LightningElement } from 'lwc';

/**
 * Module-level counter used to guarantee unique DOM ids for the
 * section-body element when multiple instances of this component
 * exist on the same page (required so aria-controls always resolves
 * to exactly one element).
 */
let instanceCounter = 0;

/**
 * A reusable WAI-ARIA disclosure (collapsible section).
 *
 * Usage:
 *   <c-collapsible-section>
 *       <span slot="title">Billing details</span>
 *       <p>Any body content…</p>
 *   </c-collapsible-section>
 */
export default class CollapsibleSection extends LightningElement {
    /**
     * Tracks the expanded/collapsed state. The section starts collapsed.
     * @type {boolean}
     */
    isExpanded = false;

    /**
     * Unique id of the section-body element, referenced by aria-controls.
     * @type {string}
     */
    bodyId;

    constructor() {
        super();
        instanceCounter += 1;
        this.bodyId = `collapsible-section-body-${instanceCounter}`;
    }

    /**
     * Value bound to the toggle button's aria-expanded attribute.
     */
    get ariaExpanded() {
        return this.isExpanded ? 'true' : 'false';
    }

    /**
     * The body div is always rendered so aria-controls always resolves;
     * the `hidden` attribute is applied only while collapsed.
     */
    get isCollapsed() {
        return !this.isExpanded;
    }

    /**
     * Toggles the disclosure state. Using a native <button> means
     * Enter/Space activation and focus semantics come for free.
     */
    handleToggle() {
        this.isExpanded = !this.isExpanded;
    }
}
