/**
 * @file Displays the contacts of an account. The parent owns the data and
 *       passes it in via the public `contacts` property; this component
 *       performs no data fetching.
 */
import { api, LightningElement } from 'lwc';

export default class AccountContactList extends LightningElement {
    /**
     * Array of contacts shaped as `{ Id, Name, Title }`, owned by the parent.
     * @type {Array<{Id: string, Name: string, Title?: string}>|null}
     */
    @api contacts;

    /**
     * True when there are no contacts to display (undefined, null or empty).
     * @type {boolean}
     */
    get hasContacts() {
        return Array.isArray(this.contacts) && this.contacts.length > 0;
    }

    /**
     * Count paragraph text: "1 contact" for exactly one contact,
     * "<n> contacts" otherwise.
     * @type {string}
     */
    get contactCount() {
        const count = this.contacts.length;
        return count === 1 ? '1 contact' : `${count} contacts`;
    }

    /**
     * Contacts sorted by Name ascending using locale-aware comparison.
     * Returns a new array so the parent-owned array is never mutated.
     * @type {Array<{Id: string, Name: string, Title?: string}>}
     */
    get sortedContacts() {
        return [...this.contacts].sort((a, b) =>
            a.Name.localeCompare(b.Name)
        );
    }
}
