```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY_MS = 300;
const MIN_SEARCH_LENGTH = 2;

export default class ContactSearch extends LightningElement {
    searchTerm = '';
    contacts = [];
    errorMessage = '';
    hasResults = false;

    timerId;
    requestId = 0;
    isDestroyed = false;

    handleChange(event) {
        this.searchTerm = event.target.value;
        this.queueSearch();
    }

    queueSearch() {
        // Cancel any pending debounced search from a previous keystroke.
        clearTimeout(this.timerId);
        this.timerId = undefined;

        // Invalidate any in-flight request so a late response is ignored.
        this.requestId += 1;
        const currentRequestId = this.requestId;

        const trimmedTerm = (this.searchTerm || '').trim();

        if (trimmedTerm.length < MIN_SEARCH_LENGTH) {
            this.contacts = [];
            this.hasResults = false;
            this.errorMessage = '';
            return;
        }

        this.timerId = setTimeout(() => {
            this.runSearch(trimmedTerm, currentRequestId);
        }, DEBOUNCE_DELAY_MS);
    }

    async runSearch(trimmedTerm, currentRequestId) {
        try {
            const results = await searchContacts({ searchTerm: trimmedTerm });

            // Ignore if a newer request was made or the component was removed.
            if (this.isDestroyed || currentRequestId !== this.requestId) {
                return;
            }

            this.contacts = results || [];
            this.hasResults = this.contacts.length > 0;
            this.errorMessage = '';
        } catch (error) {
            if (this.isDestroyed || currentRequestId !== this.requestId) {
                return;
            }
            this.contacts = [];
            this.hasResults = false;
            this.errorMessage = error?.body?.message ?? error?.message ?? 'Unknown error';
        }
    }

    disconnectedCallback() {
        // Stop the pending debounce and invalidate any in-flight request.
        this.isDestroyed = true;
        clearTimeout(this.timerId);
        this.timerId = undefined;
        this.requestId += 1;
    }
}
