import { LightningElement, api, wire, track } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import { updateRecord } from 'lightning/uiRecordApi';
import { refreshApex } from '@salesforce/apex';
import getContacts from '@salesforce/apex/ContactController.getContacts';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text', editable: false },
    { label: 'Title', fieldName: 'Title', type: 'text', editable: true },
    { label: 'Phone', fieldName: 'Phone', type: 'phone', editable: true },
    { label: 'Email', fieldName: 'Email', type: 'email', editable: true }
];

export default class AccountContactsTable extends LightningElement {
    @api recordId;

    @track draftValues = [];

    columns = COLUMNS;

    contactsResult;

    @wire(getContacts, { accountId: '$recordId' })
    wiredContacts(result) {
        this.contactsResult = result;
        if (result.error) {
            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Error loading contacts',
                    message: result.error.body ? result.error.body.message : result.error.message,
                    variant: 'error'
                })
            );
        }
    }

    get data() {
        return this.contactsResult && this.contactsResult.data
            ? this.contactsResult.data
            : [];
    }

    handleSave(event) {
        const drafts = event.detail.draftValues;
        if (!drafts || drafts.length === 0) {
            return;
        }

        const savePromises = drafts.map((draft) =>
            updateRecord({ fields: { ...draft } })
        );

        Promise.all(savePromises)
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Contacts updated',
                        variant: 'success'
                    })
                );
                this.draftValues = [];
                refreshApex(this.contactsResult);
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Could not save contacts',
                        message:
                            error.body && error.body.message
                                ? error.body.message
                                : error.message,
                        variant: 'error'
                    })
                );
            });
    }
}
