import { api, LightningElement } from 'lwc';
import Favorite_Add from '@salesforce/label/c.Favorite_Add';
import Favorite_Remove from '@salesforce/label/c.Favorite_Remove';

export default class FavoriteToggle extends LightningElement {
    labels = {
        add: Favorite_Add,
        remove: Favorite_Remove,
    };

    // Internal reactive copy of the favorite state. The @api getter/setter
    // lets the parent push updates (e.g. after a server refresh), while the
    // click handler can optimistically flip the local value immediately.
    _favorite = false;

    @api
    get favorite() {
        return this._favorite;
    }

    set favorite(value) {
        this._favorite = !!value;
    }

    /**
     * Label of the action a click will perform: when the record is already a
     * favourite, clicking removes it; otherwise clicking adds it.
     */
    get actionLabel() {
        return this._favorite ? this.labels.remove : this.labels.add;
    }

    get ariaPressed() {
        return this._favorite ? 'true' : 'false';
    }

    get iconName() {
        return this._favorite ? 'utility:favorite' : 'utility:favorite_alt';
    }

    handleClick() {
        // Optimistic UI: flip the displayed state immediately, then notify
        // the parent so it can persist the change and (if needed) sync back.
        this._favorite = !this._favorite;
        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: {
                    favorite: this._favorite,
                },
            }),
        );
    }
}
