import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const POLLING_INTERVAL_MS = 60 * 1000;

export default class QueueMonitor extends LightningElement {
    waiting;
    longestWaitMinutes;
    error;
    isLoaded = false;
    isInFlight = false;
    timerId;

    connectedCallback() {
        // Load immediately on insertion, then poll every 60 seconds.
        this.loadStats();
        this.startPolling();
        document.addEventListener('visibilitychange', this.handleVisibilityChange);
    }

    disconnectedCallback() {
        // Stop polling and stop listening so nothing keeps running
        // or calls Apex after the component is removed from the page.
        this.stopPolling();
        document.removeEventListener('visibilitychange', this.handleVisibilityChange);
    }

    /**
     * Arrow function so `this` is bound correctly when used as an
     * event listener, and so removeEventListener receives the same
     * reference that addEventListener received.
     */
    handleVisibilityChange = () => {
        if (document.visibilityState === 'visible') {
            // Page became visible again: load immediately and restart
            // the single polling loop so the next refresh is a full
            // interval away (never two loops at once).
            this.loadStats();
            this.startPolling();
        }
        // While hidden we make no requests: loadStats() also guards on
        // visibilityState, so any interval tick that fires while hidden
        // is skipped.
    };

    startPolling() {
        // Clear any existing timer first, guaranteeing exactly one
        // polling loop at a time.
        this.stopPolling();
        this.timerId = setInterval(() => {
            this.loadStats();
        }, POLLING_INTERVAL_MS);
    }

    stopPolling() {
        if (this.timerId !== undefined) {
            clearInterval(this.timerId);
            this.timerId = undefined;
        }
    }

    loadStats() {
        // Never start a request while one is still in flight,
        // and never while the tab is hidden.
        if (this.isInFlight || document.visibilityState === 'hidden') {
            return;
        }

        this.isInFlight = true;
        getQueueStats()
            .then((stats) => {
                this.waiting = stats.waiting;
                this.longestWaitMinutes = stats.longestWaitMinutes;
                // Successful refresh clears any previous error.
                this.error = undefined;
                this.isLoaded = true;
            })
            .catch((e) => {
                // Keep polling; just surface the error until the next
                // successful refresh replaces it.
                this.error = e;
            })
            .finally(() => {
                this.isInFlight = false;
            });
    }

    get errorMessage() {
        return this.error?.body?.message;
    }
}
