import { LightningElement, api } from 'lwc';

let uidCounter = 0;

export default class StatusListbox extends LightningElement {
    static renderMode = 'light';

    @api label;
    @api options = [];

    _value = '';
    _activeValue;

    uid;

    constructor() {
        super();
        uidCounter += 1;
        this.uid = `status-listbox-${uidCounter}`;
    }

    @api
    get value() {
        return this._value;
    }

    set value(newValue) {
        const next = newValue ?? '';
        this._value = next;
        // When the parent changes the value, the active option moves to it.
        this._activeValue = next;
    }

    /**
     * Index of the active option. Falls back to the selected option,
     * then to the first option, when no explicit active value is set
     * or when the active value no longer exists in the options.
     */
    get activeIndex() {
        if (!this.options || this.options.length === 0) {
            return -1;
        }
        const activeIdx = this.options.findIndex(
            (option) => option.value === this._activeValue
        );
        if (activeIdx !== -1) {
            return activeIdx;
        }
        const selectedIdx = this.options.findIndex(
            (option) => option.value === this._value
        );
        if (selectedIdx !== -1) {
            return selectedIdx;
        }
        return 0;
    }

    get renderedOptions() {
        return (this.options ?? []).map((option, index) => {
            const isSelected = option.value === this._value;
            return {
                ...option,
                id: `${this.uid}-option-${index}`,
                isSelected,
                className: option.value === this.activeIndexValue ? 'option-active' : '',
            };
        });
    }

    // Resolve the active value without going through the index logic twice.
    get activeIndexValue() {
        const idx = this.activeIndex;
        if (idx === -1) {
            return undefined;
        }
        return this.options[idx].value;
    }

    get activeOptionId() {
        const idx = this.activeIndex;
        if (idx === -1) {
            return undefined;
        }
        return `${this.uid}-option-${idx}`;
    }

    handleKeyDown(event) {
        const length = this.options ? this.options.length : 0;
        if (length === 0) {
            return;
        }

        switch (event.key) {
            case 'ArrowDown': {
                const current = this.activeIndex;
                this._activeValue = this.options[Math.min(current + 1, length - 1)].value;
                event.preventDefault();
                break;
            }
            case 'ArrowUp': {
                const current = this.activeIndex;
                this._activeValue = this.options[Math.max(current - 1, 0)].value;
                event.preventDefault();
                break;
            }
            case 'Home': {
                this._activeValue = this.options[0].value;
                event.preventDefault();
                break;
            }
            case 'End': {
                this._activeValue = this.options[length - 1].value;
                event.preventDefault();
                break;
            }
            case 'Enter':
            case ' ': {
                const idx = this.activeIndex;
                if (idx !== -1) {
                    this.selectValue(this.options[idx].value);
                }
                event.preventDefault();
                break;
            }
            default:
                // All other keys (including Tab) keep their default behaviour.
                break;
        }
    }

    handleClick(event) {
        const value = event.currentTarget.dataset.value;
        if (value !== undefined) {
            this.selectValue(value);
        }
    }

    selectValue(value) {
        // Clicking or keyboard selection makes the option active...
        this._activeValue = value;
        // ...and selects it, but only dispatch when the selection actually changes.
        if (this._value !== value) {
            this._value = value;
            this.dispatchEvent(
                new CustomEvent('change', {
                    detail: { value },
                })
            );
        }
    }
}
