import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    // Backing fields — never mutated after being set, only replaced.
    _heading = '';
    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    // heading is display-only: store exactly what the parent set (original case),
    // expose it unchanged via the getter, and upper-case it only for rendering.
    // Using a setter (instead of mutating in connectedCallback) means later
    // changes by the parent are picked up reactively.
    @api
    get heading() {
        return this._heading;
    }
    set heading(value) {
        this._heading = value ?? '';
    }

    get headingUpper() {
        return this._heading ? this._heading.toUpperCase() : '';
    }

    // tasks: the component always works on its own deep-enough copy.
    // The setter replaces the working list whenever the parent passes a new array,
    // so this also works if tasks is assigned before/after the component connects.
    @api
    get tasks() {
        return this._tasks;
    }
    set tasks(value) {
        this._tasks = Array.isArray(value) ? value : [];
        this.items = this._tasks.map((task) => ({ ...task }));
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        // Trim and ignore empty/whitespace-only labels.
        const label = (this.newLabel ?? '').trim();
        if (!label) {
            return;
        }
        const task = { id: `new-${this.nextId++}`, label, done: false };
        // Replace the array (don't push) so the template re-renders.
        this.items = [...this.items, task];
        // Clear the input first... but capture the label for the event.
        this.newLabel = '';
        // Event name is lowercase per the LWC naming rules so that an
        // `ontaskadded` listener in the parent matches reliably.
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id; // dataset values are always strings
        // Build a new array with a new object for the toggled task:
        // mutating task.done in place is not reactive in LWC (shallow tracking),
        // which is why the counter previously didn't update.
        this.items = this.items.map((task) =>
            String(task.id) === id ? { ...task, done: !task.done } : task
        );
    }
}
