/**
 * @description Service for setting a Contact's current employer via the NPSP
 *              Affiliation model (Household Account model, Affiliations enabled).
 *
 * The heavy lifting is delegated to the NPSP standard mechanism
 * (`npsp.Affiliations_API.createPrimaryAffiliations`), which guarantees that:
 *
 *   - a Current (open-ended) primary `npsp__Affiliation__c` is created between
 *     the Contact and the Organization Account, using the default role from
 *     Affiliation Settings;
 *   - the Contact's `npsp__Primary_Affiliation__c` lookup is repointed to the
 *     Organization Account;
 *   - the Contact's previous primary affiliation is automatically demoted to
 *     non-primary and end-dated with today's date (i.e. it becomes a "Former"
 *     affiliation), so the Contact remains affiliated to their household;
 *   - household membership / Household Account lookups are untouched.
 *
 * The class itself is bulk-safe (200+ contacts in one call) and stays well
 * within its own budget of at most 2 SOQL queries and 0-2 DML statements: the
 * only DML executed here is inside the NPSP service, triggered by a single API
 * call. The two SOQL queries in this class exist purely to make the operation
 * idempotent: if a contact's current, primary affiliation already points at
 * the requested organization (and the primary affiliation lookup agrees), that
 * contact is filtered out so that absolutely nothing is written for them.
 */
public inherited sharing class EmployerService {

    /**
     * @description Sets the current employer (primary affiliation) for a batch
     *              of Contacts.
     *
     * @param employerByContactId Map of Contact Ids (keys) to the Organization
     *                            Account Id that is the Contact's current
     *                            employer (values). A null or empty map — or a
     *                            map containing only null keys/values — does
     *                            nothing.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        // 1. Null or empty map: no-op.
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        // 2. Drop null keys/values so we never attempt DML against bogus Ids.
        Map<Id, Id> requested = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id accountId = employerByContactId.get(contactId);
            if (contactId != null && accountId != null) {
                requested.put(contactId, accountId);
            }
        }
        if (requested.isEmpty()) {
            return;
        }

        // 3. Idempotency filter (SOQL query 1 of 2): find each contact's
        //    existing current (open-ended) primary affiliation, if any.
        Map<Id, Id> currentPrimaryAccountByContactId = new Map<Id, Id>();
        for (npsp__Affiliation__c aff : [
            SELECT npsp__Contact__c, npsp__Account__c
            FROM npsp__Affiliation__c
            WHERE npsp__Contact__c IN :requested.keySet()
              AND npsp__Primary__c = TRUE
              AND npsp__End_Date__c = NULL
        ]) {
            currentPrimaryAccountByContactId.put(
                (Id) aff.get('npsp__Contact__c'),
                (Id) aff.get('npsp__Account__c')
            );
        }

        // 4. Idempotency filter (SOQL query 2 of 2): also read the Contact's
        //    primary affiliation lookup so we only skip a contact when the
        //    affiliation record AND the lookup both already point at the org.
        Map<Id, Id> primaryLookupAccountByContactId = new Map<Id, Id>();
        for (Contact con : [
            SELECT npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :requested.keySet()
        ]) {
            primaryLookupAccountByContactId.put(
                con.Id,
                (Id) con.get('npsp__Primary_Affiliation__c')
            );
        }

        Map<Id, Id> toProcess = new Map<Id, Id>();
        for (Id contactId : requested.keySet()) {
            Id accountId = requested.get(contactId);
            Boolean alreadyCurrent =
                currentPrimaryAccountByContactId.get(contactId) == accountId &&
                primaryLookupAccountByContactId.get(contactId) == accountId;

            if (!alreadyCurrent) {
                toProcess.put(contactId, accountId);
            }
        }

        // Every contact already has the organization as their current, primary
        // employer: nothing changes, no duplicate affiliations are created.
        if (toProcess.isEmpty()) {
            return;
        }

        // 5. Delegate to NPSP's standard Affiliations mechanism. This single
        //    call creates/updates the primary affiliations, end-dates and
        //    de-primary-izes any previous primary employer affiliation, and
        //    repoints each Contact's Primary Affiliation lookup — all
        //    bulk-safe and without touching the Contact's Household Account.
        npsp.Affiliations_API.createPrimaryAffiliations(toProcess);
    }
}
