/**
 * @description Service for replacing the GAU Allocations of an Opportunity with
 *              percentage-based ("hard coded") allocations.
 *
 *              Each allocation is stored with both npsp__Percent__c and
 *              npsp__Amount__c. Because NPSP treats percent-based allocations as
 *              hard coded allocations, it will automatically recalculate the
 *              npsp__Amount__c values whenever the Opportunity's Amount changes,
 *              so no further code is needed to keep the split correct over time
 *              (e.g. a 60/40 split on $1,000 becomes $1,200/$800 when the
 *              Opportunity is corrected to $2,000).
 *
 *              All validation is performed before any DML is executed, so a
 *              failure never leaves the Opportunity's allocations in a partial
 *              or inconsistent state.
 */
public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    private static final Decimal MAX_TOTAL_PERCENT = 100;

    /**
     * @description Replaces all existing GAU Allocations of the given Opportunity
     *              with one allocation per entry in the supplied map.
     * @param opportunityId  Id of the Opportunity whose allocations are replaced.
     * @param percentByGauId Map of npsp__General_Accounting_Unit__c Ids to
     *                       percentages (60 means 60%). Totals below 100% are
     *                       allowed; the remainder simply stays unallocated.
     * @return The inserted npsp__Allocation__c records.
     * @throws AllocationException if the map is null/empty, any percentage is
     *         null or <= 0, the percentages total more than 100, any GAU is
     *         inactive or does not exist, or the Opportunity is missing/has no
     *         Amount.
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        validateInput(opportunityId, percentByGauId);

        // Everything below is read-only validation before any DML executes.
        List<Opportunity> opportunities = [
            SELECT Id, Amount
            FROM Opportunity
            WHERE Id = :opportunityId
        ];
        if (opportunities.isEmpty()) {
            throw new AllocationException('Opportunity not found: ' + opportunityId);
        }
        Opportunity opportunity = opportunities[0];
        if (opportunity.Amount == null) {
            throw new AllocationException('Opportunity ' + opportunityId + ' must have an Amount before GAU allocations can be created.');
        }

        validateGaus(percentByGauId.keySet());

        // Read the current allocations now (before any DML) so the delete list
        // is final even if this method is called from a context that mutates data.
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];

        List<npsp__Allocation__c> newAllocations = buildAllocations(opportunity, percentByGauId);

        // All validation passed; it is now safe to change data.
        if (!existingAllocations.isEmpty()) {
            delete existingAllocations;
        }
        insert newAllocations;

        return newAllocations;
    }

    /**
     * @description Validates the method arguments before touching the database.
     */
    private static void validateInput(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        if (opportunityId == null) {
            throw new AllocationException('An Opportunity Id is required.');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('The percentByGauId map must not be null or empty.');
        }

        Decimal totalPercent = 0;
        for (Decimal percent : percentByGauId.values()) {
            if (percent == null || percent <= 0) {
                throw new AllocationException('Every percentage must be non-null and greater than 0.');
            }
            totalPercent += percent;
        }
        if (totalPercent > MAX_TOTAL_PERCENT) {
            throw new AllocationException('The percentages total ' + totalPercent + ', which exceeds the maximum of 100.');
        }
    }

    /**
     * @description Validates that every GAU in the map exists and is active.
     */
    private static void validateGaus(Set<Id> gauIds) {
        Map<Id, npsp__General_Accounting_Unit__c> gauById = new Map<Id, npsp__General_Accounting_Unit__c>([
            SELECT Id, Name, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :gauIds
        ]);

        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gauById.get(gauId);
            if (gau == null) {
                throw new AllocationException('General Accounting Unit not found: ' + gauId);
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException('General Accounting Unit "' + gau.Name + '" (' + gauId + ') is inactive.');
            }
        }
    }

    /**
     * @description Builds one allocation per map entry, storing both the percent
     *              and the corresponding amount. Populating npsp__Percent__c is
     *              what makes NPSP recalculate the amounts automatically whenever
     *              the Opportunity Amount changes in the future.
     */
    private static List<npsp__Allocation__c> buildAllocations(Opportunity opportunity, Map<Id, Decimal> percentByGauId) {
        Decimal opportunityAmount = opportunity.Amount;
        List<npsp__Allocation__c> allocations = new List<npsp__Allocation__c>();

        for (Id gauId : percentByGauId.keySet()) {
            Decimal percent = percentByGauId.get(gauId);
            allocations.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunity.Id,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percent,
                npsp__Amount__c = (opportunityAmount * percent) / 100
            ));
        }
        return allocations;
    }
}
