public with sharing class HouseholdService {

    /**
     * Creates one new NPSP Household Account and inserts all given Contacts into
     * it. The first Contact in the list becomes the household's primary contact.
     *
     * Strategy:
     *   1. Insert the primary contact WITHOUT an AccountId. NPSP's Contact
     *      triggers (TDTM_Contact) then auto-create a Household Account for it:
     *      NPSP selects the Household Account record type itself, applies its
     *      household naming rules, generates greetings, and stamps
     *      npsp__Primary_Contact__c on the new household.
     *   2. Read back the AccountId assigned by the trigger (trigger-performed
     *      DML is not reflected on our in-memory record).
     *   3. Insert the remaining contacts with AccountId pointing at that same
     *      household. NPSP refreshes the household name and greetings to cover
     *      the full family, and the primary contact remains the first contact.
     *
     * No Account record is ever created directly by this service, so no extra
     * or empty households can be left behind, and no record type Ids are
     * hard-coded.
     *
     * @param  members  new Contacts (no Id, no AccountId) to place in one household
     * @return          the Id of the new NPSP Household Account
     * @throws IllegalArgumentException if members is null or empty
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException(
                'HouseholdService.createHousehold requires at least one contact.'
            );
        }

        // Work on clones so we never mutate the caller's records.
        Contact primary = members[0].clone(false);
        primary.Id = null;
        primary.AccountId = null;

        // Step 1: let NPSP auto-create the household from the primary contact.
        insert primary;

        // Step 2: the trigger-created AccountId is not visible on our
        // in-memory sObject, so query it back.
        primary = [
            SELECT AccountId
            FROM Contact
            WHERE Id = :primary.Id
            LIMIT 1
        ];

        Id householdId = primary.AccountId;
        if (householdId == null) {
            throw new IllegalStateException(
                'NPSP did not create a household account for the primary contact.'
            );
        }

        // Step 3: attach the remaining family members to the same household.
        if (members.size() > 1) {
            List<Contact> familyMembers = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                Contact member = members[i].clone(false);
                member.Id = null;
                member.AccountId = householdId;
                familyMembers.add(member);
            }
            insert familyMembers;
        }

        return householdId;
    }
}
