```apex
/**
 * @description Service for crediting peer-to-peer fundraisers using NPSP
 *  partial soft credits (npsp__Partial_Soft_Credit__c).
 *
 *  Guarantees, per call:
 *   - The fundraiser contact ends up with exactly one OpportunityContactRole
 *     on the opportunity whose Role equals the requested role (an existing
 *     role, e.g. NPSP's "Household Member", is reused/renamed rather than
 *     duplicated).
 *   - The contact has exactly one partial soft credit on the opportunity,
 *     linked to that contact role, carrying the requested amount and role
 *     name (an existing partial soft credit is updated, not duplicated).
 *   - The primary contact of an opportunity can never receive a partial
 *     soft credit.
 *   - Full validation happens before any DML, so a failed call changes
 *     nothing.
 *   - 200 requests cost at most 3 SOQL queries and 3 DML statements.
 */
public inherited sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    /**
     * @description Adds or updates partial soft credits for the given requests.
     * @param requests The requested partial soft credits. Null/empty does nothing.
     * @throws SoftCreditService.SoftCreditException if any request is invalid.
     *         Nothing is written when validation fails.
     */
    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        // ------------------------------------------------------------------
        // 0. Guard clauses
        // ------------------------------------------------------------------
        if (requests == null || requests.isEmpty()) {
            return;
        }

        List<SoftCreditRequest> work = new List<SoftCreditRequest>();
        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest request : requests) {
            if (request == null) {
                continue;
            }
            work.add(request);
            if (request.opportunityId != null) {
                opportunityIds.add(request.opportunityId);
            }
            if (request.contactId != null) {
                contactIds.add(request.contactId);
            }
        }
        if (work.isEmpty()) {
            return;
        }

        // ------------------------------------------------------------------
        // 1. SOQL #1: opportunities needed for validation
        // ------------------------------------------------------------------
        Map<Id, Opportunity> opportunities = new Map<Id, Opportunity>(
            [
                SELECT Id, Amount, npsp__Primary_Contact__c
                FROM Opportunity
                WHERE Id IN :opportunityIds
            ]
        );

        // ------------------------------------------------------------------
        // 2. Validate the whole call before any DML
        // ------------------------------------------------------------------
        for (SoftCreditRequest request : work) {
            Opportunity opp = opportunities.get(request.opportunityId);
            if (opp == null) {
                throw new SoftCreditException(
                    'Opportunity not found: ' + request.opportunityId
                );
            }
            if (request.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'Contact ' + request.contactId +
                    ' is the primary contact on opportunity ' +
                    request.opportunityId +
                    ' and cannot receive a partial soft credit.'
                );
            }
            if (request.amount == null) {
                throw new SoftCreditException(
                    'Partial soft credit amount must not be null (opportunity ' +
                    request.opportunityId + ', contact ' + request.contactId + ').'
                );
            }
            if (request.amount <= 0) {
                throw new SoftCreditException(
                    'Partial soft credit amount must be positive (opportunity ' +
                    request.opportunityId + ', contact ' + request.contactId + ').'
                );
            }
            if (opp.Amount != null && request.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Partial soft credit amount ' + request.amount +
                    ' exceeds the opportunity amount ' + opp.Amount +
                    ' (opportunity ' + request.opportunityId +
                    ', contact ' + request.contactId + ').'
                );
            }
        }

        // ------------------------------------------------------------------
        // 3. SOQL #2: existing contact roles for every requested pair
        // ------------------------------------------------------------------
        Map<String, List<OpportunityContactRole>> existingOcrsByPair =
            new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
                SELECT Id, OpportunityId, ContactId, Role
                FROM OpportunityContactRole
                WHERE OpportunityId IN :opportunityIds
                  AND ContactId IN :contactIds
        ]) {
            String key = pairKey(ocr.OpportunityId, ocr.ContactId);
            List<OpportunityContactRole> listForPair = existingOcrsByPair.get(key);
            if (listForPair == null) {
                listForPair = new List<OpportunityContactRole>();
                existingOcrsByPair.put(key, listForPair);
            }
            listForPair.add(ocr);
        }

        // ------------------------------------------------------------------
        // 4. Build contact role upserts/deletes
        // ------------------------------------------------------------------
        List<OpportunityContactRole> ocrsToUpsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();

        for (SoftCreditRequest request : work) {
            String key = pairKey(request.opportunityId, request.contactId);
            List<OpportunityContactRole> existing = existingOcrsByPair.get(key);

            if (existing == null || existing.isEmpty()) {
                // No role yet: create exactly one with the requested role.
                ocrsToUpsert.add(new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId,
                    Role = request.role
                ));
            } else {
                // Exactly one role must remain: keep one (prefer one whose
                // role already matches) and delete any duplicates.
                Integer keepIndex = 0;
                for (Integer i = 1; i < existing.size(); i++) {
                    if (existing[i].Role == request.role &&
                        existing[keepIndex].Role != request.role) {
                        keepIndex = i;
                    }
                }
                for (Integer i = 0; i < existing.size(); i++) {
                    if (i != keepIndex) {
                        ocrsToDelete.add(existing[i]);
                    }
                }
                OpportunityContactRole kept = existing[keepIndex];
                if (kept.Role != request.role) {
                    kept.Role = request.role;
                }
                ocrsToUpsert.add(kept);
            }
        }

        // ------------------------------------------------------------------
        // 5. DML #1: upsert contact roles (updates carry their Id, inserts
        //    receive one, so we can link the partial soft credits below)
        // ------------------------------------------------------------------
        if (!ocrsToUpsert.isEmpty()) {
            upsert ocrsToUpsert;
        }

        // ------------------------------------------------------------------
        // 6. SOQL #3: existing partial soft credits for every requested pair
        // ------------------------------------------------------------------
        Map<String, npsp__Partial_Soft_Credit__c> existingPscByPair =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
                SELECT Id, npsp__Opportunity__c, npsp__Contact__c
                FROM npsp__Partial_Soft_Credit__c
                WHERE npsp__Opportunity__c IN :opportunityIds
                  AND npsp__Contact__c IN :contactIds
        ]) {
            existingPscByPair.put(
                pairKey(psc.npsp__Opportunity__c, psc.npsp__Contact__c),
                psc
            );
        }

        // ------------------------------------------------------------------
        // 7. Build partial soft credit upserts (update or insert)
        // ------------------------------------------------------------------
        List<npsp__Partial_Soft_Credit__c> pscsToUpsert =
            new List<npsp__Partial_Soft_Credit__c>();
        for (Integer i = 0; i < work.size(); i++) {
            SoftCreditRequest request = work[i];
            String key = pairKey(request.opportunityId, request.contactId);
            npsp__Partial_Soft_Credit__c psc = existingPscByPair.get(key);
            if (psc == null) {
                psc = new npsp__Partial_Soft_Credit__c();
            }
            psc.npsp__Opportunity__c = request.opportunityId;
            psc.npsp__Contact__c = request.contactId;
            psc.npsp__Amount__c = request.amount;
            psc.npsp__Role__c = request.role;
            psc.npsp__Opportunity_Contact_Role__c = ocrsToUpsert[i].Id;
            pscsToUpsert.add(psc);
        }

        // ------------------------------------------------------------------
        // 8. DML #2 and #3: upsert partial soft credits, then remove any
        //    duplicate contact roles (after the soft credits have been
        //    relinked to the kept role)
        // ------------------------------------------------------------------
        if (!pscsToUpsert.isEmpty()) {
            upsert pscsToUpsert;
        }
        if (!ocrsToDelete.isEmpty()) {
            delete ocrsToDelete;
        }
    }

    /**
     * @description Stable composite key for an (opportunity, contact) pair.
     */
    private static String pairKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + '-' + String.valueOf(contactId);
    }
}
