/**
 * @description Service for converting an NPSP pledge (open Donation with its
 *              auto-generated full-amount unpaid Payment) into a monthly
 *              installment plan of Payments.
 *
 *              Paid and written-off Payments are treated as history and are
 *              never modified. All other (unpaid, not written-off) Payments
 *              for the Donation are deleted and replaced by the requested
 *              number of monthly installments that together equal the
 *              outstanding amount (Donation Amount minus paid and written-off
 *              Payments).
 *
 *              The class is bulk-safe and performs all validation before any
 *              DML, so a failed call never leaves the data in a partial state.
 */
public with sharing class PaymentPlanService {

    /** Thrown when the installment plan cannot be scheduled. */
    public class PaymentPlanException extends Exception {}

    /** Scale used when splitting the outstanding amount per installment. */
    private static final Integer CURRENCY_SCALE = 2;

    /**
     * @description Replaces the open (unpaid, not written-off) Payments of a
     *              Donation with `numberOfPayments` equal monthly installments.
     *              Payment i (0-based) is scheduled on firstPaymentDate + i months.
     *              Each installment is the outstanding amount divided by the
     *              number of payments, rounded down to the cent
     *              (RoundingMode.DOWN); the last installment absorbs any
     *              remainder so the installments sum exactly to the outstanding
     *              amount.
     * @param opportunityId     Id of the Donation (Opportunity) to schedule.
     * @param numberOfPayments  Number of monthly installments to create. Must be >= 1.
     * @param firstPaymentDate  Scheduled date of the first installment.
     * @return The inserted Payments, in schedule order.
     * @throws PaymentPlanService.PaymentPlanException if numberOfPayments is null
     *         or < 1, if the Donation is closed, or if the outstanding amount is
     *         not greater than zero. Nothing is modified in those cases.
     */
    @AuraEnabled
    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {
        // ---- Validate input parameters -------------------------------------
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException(
                'numberOfPayments must be at least 1 (received: ' + numberOfPayments + ').'
            );
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('firstPaymentDate is required.');
        }

        // ---- Load the Donation ---------------------------------------------
        Opportunity opp = [
            SELECT Id, IsClosed, Amount
            FROM Opportunity
            WHERE Id = :opportunityId
        ];
        if (opp.IsClosed) {
            throw new PaymentPlanException(
                'Cannot schedule installments: the Donation is closed.'
            );
        }

        // ---- Classify existing Payments and compute the outstanding amount --
        // Paid and written-off Payments are history: keep them and subtract
        // their amounts from the outstanding balance.
        Decimal outstanding = opp.Amount == null ? 0 : opp.Amount;
        List<npe01__OppPayment__c> openPayments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Paid__c, Write_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
              AND npe01__Paid__c = false
              AND Write_Off__c = false
        ];
        List<npe01__OppPayment__c> historyPayments = [
            SELECT npe01__Payment_Amount__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
              AND (npe01__Paid__c = true OR Write_Off__c = true)
        ];
        for (npe01__OppPayment__c historyPayment : historyPayments) {
            if (historyPayment.npe01__Payment_Amount__c != null) {
                outstanding -= historyPayment.npe01__Payment_Amount__c;
            }
        }

        if (outstanding <= 0) {
            throw new PaymentPlanException(
                'Cannot schedule installments: the outstanding amount must be greater than zero.'
            );
        }

        // ---- Delete the open Payments before any other DML -------------------
        if (!openPayments.isEmpty()) {
            delete openPayments;
        }

        // ---- Build the new installment Payments ------------------------------
        // Per-installment amount: outstanding / n, rounded DOWN to the cent.
        Decimal installmentAmount = outstanding.divide(
            numberOfPayments,
            CURRENCY_SCALE,
            RoundingMode.DOWN
        );
        // The last installment absorbs the remainder so the sum is exact.
        Decimal lastInstallmentAmount = outstanding
            - (installmentAmount * (numberOfPayments - 1));

        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        for (Integer i = 0; i < numberOfPayments; i++) {
            newPayments.add(new npe01__OppPayment__c(
                npe01__Opportunity__c = opp.Id,
                npe01__Payment_Amount__c = (i == numberOfPayments - 1)
                    ? lastInstallmentAmount
                    : installmentAmount,
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Paid__c = false
            ));
        }

        insert newPayments;

        // Inserted in schedule order; returned with Ids populated.
        return newPayments;
    }
}
