/**
 * GiftService
 * -----------
 * Records a gift that has already been received, for an org running the
 * Nonprofit Success Pack (NPSP) with the Household Account model and
 * NPSP Payments enabled.
 *
 * NPSP expectations honored by this service:
 *   - The Opportunity is attributed to the contact's household Account
 *     (on the Household Account model, Contact.AccountId IS the household).
 *   - The donor contact is the primary Opportunity Contact Role with the
 *     "Donor" role; every other member of the household is added with the
 *     "Household Member" role (NPSP's standard household credit roles).
 *   - Exactly one Payment (npe01__OppPayment__c) is created for the full
 *     amount, marked Paid, with its payment date equal to the gift date.
 *     NPSP's automatic payment creation is suppressed on the Opportunity via
 *     the "Do Not Automatically Create Payment" field
 *     (npe01__Do_Not_Automatically_Create_Payment__c) so that the payment we
 *     insert ourselves is the only one - no duplicates can be produced by
 *     NPSP's Manage Payments trigger logic.
 */
public with sharing class GiftService {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String ROLE_DONOR = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';

    /**
     * Records a Closed Won donation from the given contact and returns the
     * Opportunity Id.
     *
     * @param contactId Id of the donor Contact (must exist and belong to a
     *                  household Account).
     * @param amount    Gift amount; must be non-null and strictly positive.
     * @param giftDate  Date the gift was received; used as CloseDate and as
     *                  the payment date.
     * @return          Id of the created Opportunity.
     * @throws IllegalArgumentException if the contact does not exist, the
     *         contact has no household Account, or amount is null/zero/negative.
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        // ---- Input validation -------------------------------------------------
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException(
                'Amount must be a positive, non-zero value.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }
        if (contactId == null) {
            throw new IllegalArgumentException('Contact Id is required.');
        }

        // ---- Contact lookup (no exception leak; we throw IAE per contract) ----
        List<Contact> contacts = [
            SELECT Id, AccountId, FirstName, LastName
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException(
                'Contact does not exist: ' + contactId);
        }
        Contact donor = contacts[0];

        if (String.isBlank(donor.AccountId)) {
            throw new IllegalArgumentException(
                'Contact is not associated with a household account.');
        }

        // ---- Household members (one query, outside any loop) ------------------
        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :donor.AccountId
        ];

        // ---- Opportunity ------------------------------------------------------
        // AccountId = household Account per the Household Account model.
        // Suppress NPSP auto-payment creation so we control the single payment.
        Opportunity opp = new Opportunity(
            Name = buildOpportunityName(donor, giftDate),
            StageName = STAGE_CLOSED_WON,
            CloseDate = giftDate,
            AccountId = donor.AccountId,
            npe01__Do_Not_Automatically_Create_Payment__c = true
        );
        insert opp;

        // ---- Opportunity Contact Roles -----------------------------------------
        // Donor: "Donor" role, primary. All other household members:
        // "Household Member". Roles are built from the distinct household
        // query result, so a contact can never end up with two roles.
        Set<Id> processedContactIds = new Set<Id>();
        List<OpportunityContactRole> roles = new List<OpportunityContactRole>();
        for (Contact member : householdMembers) {
            if (!processedContactIds.add(member.Id)) {
                // Defensive: skip any duplicate rows from the query.
                continue;
            }
            Boolean isDonor = (member.Id == contactId);
            roles.add(new OpportunityContactRole(
                OpportunityId = opp.Id,
                ContactId     = member.Id,
                Role          = isDonor ? ROLE_DONOR : ROLE_HOUSEHOLD_MEMBER,
                IsPrimary     = isDonor
            ));
        }
        insert roles;

        // ---- Payment ------------------------------------------------------------
        // Exactly one payment: full amount, Paid, dated on the gift date.
        // npe01__Payment_Date__c is a formula over Paid_Date / Scheduled_Date,
        // so setting both guarantees the correct payment date.
        npe01__OppPayment__c payment = new npe01__OppPayment__c(
            npe01__Opportunity__c     = opp.Id,
            npe01__Scheduled_Amount__c = amount,
            npe01__Scheduled_Date__c   = giftDate,
            npe01__Paid__c             = true,
            npe01__Paid_Date__c        = giftDate
        );
        insert payment;

        return opp.Id;
    }

    /**
     * Builds the Opportunity Name, e.g. "Jane Smith Donation 2026-03-01".
     * Handles contacts without a FirstName ("Smith Donation 2026-03-01").
     */
    private static String buildOpportunityName(Contact donor, Date giftDate) {
        String firstNamePart = String.isBlank(donor.FirstName)
            ? ''
            : donor.FirstName + ' ';
        return firstNamePart + donor.LastName + ' Donation ' + formatIsoDate(giftDate);
    }

    /**
     * Formats a Date as yyyy-MM-dd (locale-independent), zero-padding
     * month and day.
     */
    private static String formatIsoDate(Date d) {
        String month = String.valueOf(d.month());
        String day = String.valueOf(d.day());
        if (month.length() < 2) {
            month = '0' + month;
        }
        if (day.length() < 2) {
            day = '0' + day;
        }
        return String.valueOf(d.year()) + '-' + month + '-' + day;
    }
}
