/**
 * @description NPSP Table-Driven Trigger Management (TDTM) handler that creates a
 *              follow-up "thank-you call" Task for major gifts (Closed Won,
 *              Amount >= 5000).
 *
 *              Registration (done by the admin, not in code):
 *                Object:         Opportunity
 *                Trigger Action: AfterInsert;AfterUpdate
 *                Class:          OPP_MajorGiftFollowUp_TDTM
 *                Load Order:     5
 *                Asynchronous:   false
 *
 *              Because this class extends npsp.TDTM_Runnable, it is invoked by
 *              NPSP's TDTM dispatcher only while its npsp__Trigger_Handler__c
 *              record is Active — deactivating the Trigger Handler record stops
 *              this handler. No Apex trigger is required (or used).
 *
 *              DML is returned to the TDTM framework via the dmlWrapper so the
 *              dispatcher executes it (one INSERT statement) after all handlers
 *              have run, avoiding recursion and staying within the handler's
 *              DML budget. No SOQL is executed at all: every value needed for
 *              the Task (Owner, Primary Contact, CloseDate) is available on the
 *              in-memory Opportunity records, so 200 opportunities process in a
 *              single transaction with 0 SOQL and 1 DML statement.
 *
 *              Duplicate protection: on AfterUpdate a Task is only created when
 *              the Opportunity transitions INTO the qualified state (was not
 *              "Closed Won with Amount >= 5000" before the update). A gift that
 *              already qualified and is merely edited will not produce a second
 *              Task.
 */
public inherited sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final String WON_STAGE = 'Closed Won';
    private static final Decimal MIN_AMOUNT = 5000;
    private static final Integer FOLLOW_UP_OFFSET_DAYS = 3;
    private static final String TASK_SUBJECT = 'Major gift thank-you call';

    /**
     * @description TDTM entry point called by NPSP's dispatcher.
     * @param newRecords    Trigger.new (the Opportunities in this context)
     * @param oldRecords    Trigger.old (populated on update; null on insert)
     * @param triggerAction The after trigger action being fired
     * @param sobjectType   Describe results for the triggering object
     * @return dmlWrapper containing at most one INSERT of the follow-up Tasks
     */
    public override npsp.TDTM_Runnable.dmlWrapper run(
        List<SObject> newRecords,
        List<SObject> oldRecords,
        npsp.TDTM_Runnable.TriggerActionEnum triggerAction,
        Schema.DescribeSObjectResult[] sobjectType
    ) {
        npsp.TDTM_Runnable.dmlWrapper wrapper = new npsp.TDTM_Runnable.dmlWrapper();

        if (newRecords == null || newRecords.isEmpty()) {
            return wrapper;
        }

        Boolean isInsert = (triggerAction == npsp.TDTM_Runnable.TriggerActionEnum.AfterInsert);
        Boolean isUpdate = (triggerAction == npsp.TDTM_Runnable.TriggerActionEnum.AfterUpdate);

        // Defensive: the Trigger Handler record scopes us to AfterInsert;AfterUpdate,
        // but never act on actions outside the supported behaviour.
        if (!isInsert && !isUpdate) {
            return wrapper;
        }

        // Index the pre-update images for the "was not qualified before" check.
        Map<Id, Opportunity> previous = new Map<Id, Opportunity>();
        if (isUpdate && oldRecords != null) {
            for (SObject oldRecord : oldRecords) {
                Opportunity oldOpp = (Opportunity) oldRecord;
                previous.put(oldOpp.Id, oldOpp);
            }
        }

        List<Task> followUpTasks = new List<Task>();

        for (SObject record : newRecords) {
            Opportunity opp = (Opportunity) record;

            if (!isQualified(opp)) {
                continue;
            }

            if (isUpdate) {
                Opportunity oldOpp = previous.get(opp.Id);
                // Already qualified before this update: skip so editing an
                // existing major gift never creates a duplicate Task.
                if (oldOpp != null && isQualified(oldOpp)) {
                    continue;
                }
            }

            followUpTasks.add(buildTask(opp));
        }

        if (!followUpTasks.isEmpty()) {
            // Hand the single INSERT back to the TDTM framework rather than
            // issuing DML here, so the dispatcher controls execution and
            // recursion handling.
            npsp.TDTM_Runnable.dml insertRequest = new npsp.TDTM_Runnable.dml();
            insertRequest.sObjects = followUpTasks;
            insertRequest.method = System.Method.INSERT;
            wrapper.dmlNew.add(insertRequest);
        }

        return wrapper;
    }

    /**
     * @description True when the Opportunity is Closed Won with Amount >= 5000.
     *              A null Amount never qualifies.
     */
    private static Boolean isQualified(Opportunity opp) {
        return WON_STAGE.equals(opp.StageName)
            && opp.Amount != null
            && opp.Amount >= MIN_AMOUNT;
    }

    /**
     * @description Builds the thank-you call Task for one qualifying Opportunity.
     *              OwnerId = opportunity owner, WhoId = primary contact (omitted
     *              when null), ActivityDate = CloseDate + 3 days (omitted when
     *              CloseDate is null).
     */
    private static Task buildTask(Opportunity opp) {
        Task followUp = new Task(
            Subject = TASK_SUBJECT,
            Priority = 'High',
            Status = 'Not Started',
            WhatId = opp.Id,
            OwnerId = opp.OwnerId
        );

        if (opp.npsp__Primary_Contact__c != null) {
            followUp.WhoId = opp.npsp__Primary_Contact__c;
        }

        if (opp.CloseDate != null) {
            followUp.ActivityDate = opp.CloseDate + FOLLOW_UP_OFFSET_DAYS;
        }

        return followUp;
    }
}
