/**
 * RecordAccessService
 *
 * Returns the subset of the given record IDs that the running user is actually
 * allowed to edit, as reported by the UserRecordAccess object (HasEditAccess).
 *
 * Design notes:
 * - UserRecordAccess takes object permissions, record ownership, sharing rules,
 *   role hierarchy, manual shares, and View All / Modify All into account, and
 *   respects the "with sharing" context of the calling transaction.
 * - The RecordId filter on UserRecordAccess accepts a maximum of 200 IDs per
 *   query, so the input is chunked. With chunks of 200, a full 2,000-ID call
 *   uses 10 SOQL queries, well within the 20-query budget.
 * - Records that are returned as editable are added to the result set; IDs not
 *   present in UserRecordAccess results (or with HasEditAccess = false) are
 *   simply excluded.
 * - Null or empty input yields an empty set, never null.
 */
public with sharing class RecordAccessService {

    /**
     * Maximum number of RecordId values allowed in a single UserRecordAccess
     * query filter (Salesforce limit).
     */
    @TestVisible
    private static final Integer CHUNK_SIZE = 200;

    /**
     * Returns the subset of recordIds the running user can edit.
     *
     * @param recordIds up to 2,000 record IDs, possibly across different objects
     * @return the editable subset; empty set (never null) for null/empty input
     */
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();

        // Null or empty input: return an empty set immediately.
        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        // Copy into a list for chunking. Using a Set as the source also
        // de-duplicates the input so each ID is checked exactly once.
        List<Id> idList = new List<Id>(recordIds);

        for (Integer startIndex = 0; startIndex < idList.size(); startIndex += CHUNK_SIZE) {
            Integer endIndex = Math.min(startIndex + CHUNK_SIZE, idList.size());
            List<Id> chunk = idList.subList(startIndex, endIndex);

            // UserRecordAccess evaluates the full access calculation for the
            // running user (object CRUD, sharing, role hierarchy, ownership,
            // View All / Modify All, etc.) for each RecordId in the filter.
            for (UserRecordAccess access : [
                SELECT RecordId
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                  AND RecordId IN :chunk
                  AND HasEditAccess = true
            ]) {
                editable.add(access.RecordId);
            }
        }

        return editable;
    }
}
```

