```java
public with sharing class DiscountApprovalService {

    private static final Decimal MAX_STANDARD_DISCOUNT = 15;

    /**
     * Returns true if the running user may approve the given discount percentage.
     * - null or negative discounts: false
     * - 0 through 15 inclusive: true
     * - above 15: true only if the user holds the Approve_Large_Discount custom permission
     */
    @AuraEnabled
    public static Boolean canApprove(Decimal discountPercent) {
        if (discountPercent == null || discountPercent < 0) {
            return false;
        }
        if (discountPercent <= MAX_STANDARD_DISCOUNT) {
            return true;
        }
        // Check the custom permission itself (Feature Management), regardless of
        // which permission set or permission set group granted it.
        return FeatureManagement.checkPermission('Approve_Large_Discount');
    }
}
