public with sharing class EmployeeDirectoryService {

    private static final List<String> CUSTOM_FIELD_APINAMES =
        new List<String>{ 'Department__c', 'Salary__c', 'Personal_Email__c' };

    /**
     * Returns the FB_Employee__c records visible to the running user via sharing,
     * ordered by Name ascending, containing only the fields the user can read.
     * Fields the user cannot read (per FLS) are omitted entirely from the
     * returned records rather than returned as null. If the user cannot read
     * the object at all, an empty list is returned.
     */
    public static List<FB_Employee__c> getDirectory() {
        // Respect object-level read access; never bypass sharing (with sharing) or FLS.
        Schema.DescribeSObjectResult describeResult = FB_Employee__c.SObjectType.getDescribe();
        if (!describeResult.isQueryable()) {
            return new List<FB_Employee__c>();
        }

        // Id and Name are always part of the record; add each custom field only
        // when the running user has read (FLS) access to it.
        List<String> queryFields = new List<String>{ 'Id', 'Name' };

        Map<String, Schema.SObjectField> fieldMap = describeResult.fields.getMap();
        for (String apiName : CUSTOM_FIELD_APINAMES) {
            Schema.SObjectField field = fieldMap.get(apiName);
            if (field != null && field.getDescribe().isAccessible()) {
                queryFields.add(apiName);
            }
        }

        String soql = 'SELECT ' + String.join(queryFields, ', ')
            + ' FROM FB_Employee__c'
            + ' ORDER BY Name ASC';

        return Database.query(soql);
    }
}
