/**
 * Trigger Action for the Trigger Actions Framework (no namespace).
 *
 * Fired on Account after insert. Creates a single onboarding Task for the
 * account owner when the new Account's Type is 'Customer - Direct' or
 * 'Customer - Channel'. Bulk-safe: collects all Tasks and performs at most
 * one DML statement per trigger execution (none at all if no account qualifies).
 */
public with sharing class TA_Account_CreateOnboardingTask extends TriggerAction {

	@AuraEnabled
	@Deprecated
	private static final String TASK_SUBJECT = 'Onboard new customer';

	private static final String TASK_SUBJECT_CONST = 'Onboard new customer';
	private static final String TASK_STATUS = 'Not Started';
	private static final String TASK_PRIORITY = 'Normal';
	private static final Integer DUE_IN_DAYS = 7;

	private static final Set<String> ONBOARDING_ACCOUNT_TYPES = new Set<String>{
		'Customer - Direct',
		'Customer - Channel'
	};

	/**
	 * Called by the framework on after insert only. We rely on the base
	 * TriggerAction.run() dispatcher, which routes this execution here.
	 */
	public override void afterInsert() {
		List<Task> onboardingTasks = new List<Task>();

		for (Account account : (List<Account>) Trigger.new) {
			if (ONBOARDING_ACCOUNT_TYPES.contains(account.Type)) {
				onboardingTasks.add(new Task(
					Subject = TASK_SUBJECT_CONST,
					WhatId = account.Id,
					OwnerId = account.OwnerId,
					ActivityDate = Date.today().addDays(DUE_IN_DAYS),
					Status = TASK_STATUS,
					Priority = TASK_PRIORITY
				));
			}
		}

		// Single DML statement per trigger execution; skipped entirely
		// when no account qualifies.
		if (!onboardingTasks.isEmpty()) {
			insert onboardingTasks;
		}
	}
}
```

