 * The DML is a single insert statement, so TAF handlers execute bulk-safe.
 */
public inherited sharing class ContactImportService {

    /**
     * @description Inserts the given contacts in one DML statement while
     *              bypassing only the TA_Contact_CreateWelcomeTask trigger
     *              action. All other Contact trigger actions (e.g. phone
     *              formatting) run as usual.
     * @param contacts The contacts to import. Null or empty input is a no-op.
     */
    public static void importContacts(List<Contact> contacts) {
        // Nothing to do; avoids enabling a bypass that would never be used.
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Skip only the welcome-task action for these inserts.
        // All other registered Contact actions still execute.
        Bypass.bypass('TA_Contact_CreateWelcomeTask');

        try {
            // Single DML statement; TAF handlers are bulk-safe and will
            // process the full list with the welcome-task action skipped.
            insert contacts;
        } finally {
            // Always clear the bypass, even if the DML throws, so that
            // contacts inserted later in this transaction receive their
            // welcome tasks as usual.
            Bypass.clearBypass('TA_Contact_CreateWelcomeTask');
        }
    }
}
