/**
 * @description Service class for moving books of business between reps.
 *
 * Reassigns Accounts (and all of their child Contacts) to a new owner.
 *
 * Trigger Actions Framework (TAF) behavior:
 *  - Account trigger actions are suppressed for the duration of this operation
 *    using TAF's programmatic transaction bypass (TriggerHandler.bypass), since
 *    Account actions perform expensive territory recalculations that are not
 *    relevant to an ownership transfer.
 *  - Contact trigger actions run normally (no bypass is applied to Contact).
 *  - The bypass is always cleared in a `finally` block, so Account automation
 *    behaves normally for the remainder of the transaction whether reassign()
 *    succeeds or throws.
 *
 * Design constraints honored:
 *  - Exactly two DML statements (one Account update, one Contact update), both
 *    all-or-none (default Apex DML behavior — a failed record rolls back the
 *    entire statement and a DmlException propagates to the caller unchanged).
 *  - One SOQL query (Contacts of the Accounts). The Account update sObjects are
 *    built directly from the passed Ids, so no Account query is needed.
 *  - Bulk-safe: no logic inside loops, sets/lists sized to input (up to 200
 *    Accounts and their Contacts are handled in single statements).
 */
public inherited sharing class AccountOwnershipService {

    /**
     * @description Sets OwnerId = newOwnerId on the given Accounts and on all
     *              Contacts belonging to those Accounts.
     * @param accountIds Ids of the Accounts to reassign. May be empty.
     * @param newOwnerId Id of the User who will own the Accounts and Contacts.
     * @throws DmlException Propagates unchanged to the caller if any record in
     *                      either update fails (all-or-none DML).
     */
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        // Nothing to do on empty input; guard against null to keep the SOQL
        // bind valid.
        if (accountIds == null || accountIds.isEmpty() || newOwnerId == null) {
            return;
        }

        // SOQL #1 (of max 2): all Contacts on the given Accounts, in one query.
        List<Contact> contactsToUpdate = [
            SELECT Id, OwnerId
            FROM Contact
            WHERE AccountId IN :accountIds
        ];
        for (Contact con : contactsToUpdate) {
            con.OwnerId = newOwnerId;
        }

        // Build Account update sObjects directly from the passed Ids —
        // no SOQL required.
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            accountsToUpdate.add(new Account(
                Id = accountId,
                OwnerId = newOwnerId
            ));
        }

        try {
            // TAF transaction bypass: no Account trigger actions will run for
            // this operation. Contact automation is NOT bypassed.
            TriggerHandler.bypass('Account');

            // DML #1 — Account ownership change, all Account trigger actions
            // suppressed. All-or-none by default; DmlException propagates
            // unchanged.
            update accountsToUpdate;

            // DML #2 — Contact ownership change, all Contact trigger actions
            // run normally. All-or-none by default; DmlException propagates
            // unchanged.
            update contactsToUpdate;
        } finally {
            // Always restore Account automation for the rest of the
            // transaction, whether the DML above succeeded or threw.
            TriggerHandler.clearBypass('Account');
        }
    }
}
