/**
 * DML-less tests for TA_Opportunity_GuardAmountDecrease.
 *
 * Follows the Trigger Actions Framework recommended testing pattern:
 * no DML, no SOQL. Records are constructed in memory with fake Ids
 * (TriggerTestUtility.getFakeId) and the action's beforeUpdate context
 * method is invoked directly. Errors are asserted via the SObject error
 * API (hasErrors() / getErrors()).
 */
@isTest
private class TA_Opportunity_GuardAmountDecreaseTest {

    private static final String ERROR_MESSAGE = TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE;

    /**
     * Builds an in-memory Opportunity with a fake (valid-format, non-inserted) Id.
     */
    private static Opportunity buildOpportunity(Id recordId, Decimal amount) {
        Opportunity opp = new Opportunity(
            Id = recordId,
            Name = 'Test Opp',
            StageName = 'Prospecting',
            Amount = amount
        );
        return opp;
    }

    /**
     * Builds matched new/old in-memory record pairs around a single Amount transition.
     */
    private static List<Opportunity> buildPair(Id recordId, Decimal oldAmount, Decimal newAmount) {
        Opportunity oldOpp = buildOpportunity(recordId, oldAmount);
        Opportunity newOpp = buildOpportunity(recordId, newAmount);
        return new List<Opportunity>{ newOpp, oldOpp };
    }

    @isTest
    static void testReductionMoreThanHalfIsRejected() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        List<Opportunity> pair = buildPair(oppId, 1000, 499);

        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(pair.get(0) != null ? new List<Opportunity>{ pair.get(0) } : null,
                            new List<Opportunity>{ pair.get(1) });

        Opportunity updated = pair.get(0);
        System.Assert.isTrue(updated.hasErrors(), 'A reduction from 1000 to 499 must be rejected.');
        System.Assert.areEqual(1, updated.getErrors().size(),
            'Exactly one error is expected on the offending record.');
        System.Assert.areEqual(ERROR_MESSAGE, updated.getErrors().get(0).getMessage(),
            'The error message must match the action\'s ERROR_MESSAGE constant.');
    }

    @isTest
    static void testReductionOfExactlyHalfIsAccepted() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        List<Opportunity> pair = buildPair(oppId, 1000, 500);

        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(new List<Opportunity>{ pair.get(0) },
                            new List<Opportunity>{ pair.get(1) });

        Opportunity updated = pair.get(0);
        System.Assert.isFalse(updated.hasErrors(),
            'A reduction of exactly half (1000 to 500) is allowed and must not add an error.');
        System.Assert.areEqual(0, updated.getErrors().size(), 'No errors are expected.');
    }

    @isTest
    static void testIncreaseIsAccepted() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        List<Opportunity> pair = buildPair(oppId, 1000, 2500);

        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(new List<Opportunity>{ pair.get(0) },
                            new List<Opportunity>{ pair.get(1) });

        Opportunity updated = pair.get(0);
        System.Assert.isFalse(updated.hasErrors(), 'An Amount increase must be accepted.');
        System.Assert.areEqual(0, updated.getErrors().size(), 'No errors are expected.');
    }

    @isTest
    static void testNullPreviousAmountIsAccepted() {
        Id oppId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        List<Opportunity> pair = buildPair(oppId, null, 10);

        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();

        // Must not throw (e.g. NullPointerException) when the old Amount is null.
        Test.startTest();
        action.beforeUpdate(new List<Opportunity>{ pair.get(0) },
                            new List<Opportunity>{ pair.get(1) });
        Test.stopTest();

        Opportunity updated = pair.get(0);
        System.Assert.isFalse(updated.hasErrors(),
            'A record whose previous Amount was null must be accepted without error.');
        System.Assert.areEqual(0, updated.getErrors().size(), 'No errors are expected.');
    }

    @isTest
    static void testMixedBatchOnlyOffendingRecordsAreFlagged() {
        Id id1 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id id2 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id id3 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);
        Id id4 = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        // Offending (1000 -> 499), accepted (1000 -> 500),
        // offending (800 -> 100), accepted (null -> 50).
        List<Opportunity> triggerNew = new List<Opportunity>{
            buildOpportunity(id1, 499),
            buildOpportunity(id2, 500),
            buildOpportunity(id3, 100),
            buildOpportunity(id4, 50)
        };
        List<Opportunity> triggerOld = new List<Opportunity>{
            buildOpportunity(id1, 1000),
            buildOpportunity(id2, 1000),
            buildOpportunity(id3, 800),
            buildOpportunity(id4, null)
        };

        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(triggerNew, triggerOld);

        // Records 1 and 3 must carry exactly one error with the constant message.
        System.Assert.areEqual(1, triggerNew[0].getErrors().size(),
            'Record 1 (1000 -> 499) must have exactly one error.');
        System.Assert.areEqual(ERROR_MESSAGE, triggerNew[0].getErrors().get(0).getMessage(),
            'Record 1 error message must match ERROR_MESSAGE.');

        System.Assert.areEqual(1, triggerNew[2].getErrors().size(),
            'Record 3 (800 -> 100) must have exactly one error.');
        System.Assert.areEqual(ERROR_MESSAGE, triggerNew[2].getErrors().get(0).getMessage(),
            'Record 3 error message must match ERROR_MESSAGE.');

        // Records 2 and 4 must be untouched.
        System.Assert.isFalse(triggerNew[1].hasErrors(),
            'Record 2 (1000 -> 500) must not have errors.');
        System.Assert.areEqual(0, triggerNew[1].getErrors().size(), 'Record 2 must have zero errors.');

        System.Assert.isFalse(triggerNew[3].hasErrors(),
            'Record 4 (null previous Amount) must not have errors.');
        System.Assert.areEqual(0, triggerNew[3].getErrors().size(), 'Record 4 must have zero errors.');
    }
}
