/**
 * Trigger Action for the Trigger Actions Framework (Mitch Spano).
 *
 * Enforces: two Contacts of the same Account may not share an email address
 * (case-insensitive comparison). Contacts without an Account or without an
 * Email are not checked.
 *
 * - On insert: every contact with an Account and an Email is checked.
 * - On update: only contacts whose Email or AccountId changed are checked,
 *   and a contact never conflicts with itself.
 * - Within one save, the first contact in the list wins; later contacts with
 *   the same (Account, Email) pair are rejected.
 * - Bulk-safe: at most one SOQL query per trigger execution.
 */
public inherited sharing class TA_Contact_PreventDuplicateEmail extends TriggerAction {

    private static final String ERROR_MESSAGE =
        'Another contact on this account already uses this email address.';

    public override void beforeInsert() {
        checkDuplicates((List<Contact>) Trigger.new, null);
    }

    public override void beforeUpdate() {
        checkDuplicates((List<Contact>) Trigger.new, Trigger.oldMap);
    }

    private void checkDuplicates(List<Contact> newRecords, Map<Id, Contact> oldMap) {
        // Determine which contacts need to be checked.
        List<Contact> contactsToCheck = new List<Contact>();
        Set<Id> checkedIds = new Set<Id>();

        for (Contact record : newRecords) {
            if (String.isBlank(record.AccountId) || String.isBlank(record.Email)) {
                continue;
            }
            if (oldMap != null) {
                Contact oldRecord = oldMap.get(record.Id);
                if (record.Email == oldRecord.Email && record.AccountId == oldRecord.AccountId) {
                    // Email and AccountId unchanged: do not check,
                    // so legacy duplicates do not block unrelated edits.
                    continue;
                }
            }
            contactsToCheck.add(record);
            checkedIds.add(record.Id);
        }

        if (contactsToCheck.isEmpty()) {
            return;
        }

        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        for (Contact record : contactsToCheck) {
            accountIds.add(record.AccountId);
            emails.add(record.Email);
        }

        // Single SOQL query: existing contacts on the same accounts whose
        // email matches (SOQL string comparison is case-insensitive).
        // Records participating in this save as "checked" are excluded;
        // conflicts among them are resolved in memory below, and a checked
        // contact therefore never conflicts with itself.
        Map<String, Id> existingKeyToId = new Map<String, Id>();
        for (Contact existing : [
                SELECT AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                  AND Email IN :emails
                  AND Id NOT IN :checkedIds
        ]) {
            existingKeyToId.put(buildKey(existing.AccountId, existing.Email), existing.Id);
        }

        // Walk the records in list order: the first contact per (Account, Email)
        // pair is accepted, each later one is rejected. A pair already present
        // in the database rejects every incoming contact using it.
        Map<String, Id> claimedInThisSave = new Map<String, Id>();
        for (Contact record : contactsToCheck) {
            String recordKey = buildKey(record.AccountId, record.Email);
            if (claimedInThisSave.containsKey(recordKey) || existingKeyToId.containsKey(recordKey)) {
                record.addError(ERROR_MESSAGE);
            } else {
                claimedInThisSave.put(recordKey, record.Id);
            }
        }
    }

    private static String buildKey(Id accountId, String email) {
        return String.valueOf(accountId) + '-' + email.toLowerCase();
    }
}
