/**
 * Trigger Action for the Trigger Actions Framework (TAF).
 * Registered on the Lead object for "Before Insert" (see Trigger_Action__mdt record).
 *
 * Normalizes messy data coming from web-to-lead and list imports:
 *  - Email:    trims leading/trailing whitespace and lower-cases (null stays null).
 *  - Company:  trims leading/trailing whitespace.
 *  - LeadSource: defaults to 'Web' when blank; an existing value is preserved.
 *
 * Runs in the before insert context, so values are clean on first save with
 * no extra DML and no SOQL. The logic is bulk-safe (single loop, no
 * statements inside the loop that hit limits) and easily handles 200 records.
 */
public inherited sharing class TA_Lead_NormalizeContactInfo extends TriggerAction {

    public override void beforeInsert(List<SObject> newList) {
        List<Lead> newLeads = (List<Lead>) newList;

        for (Lead lead : newLeads) {
            // Trim + lower-case Email; a null email stays null.
            if (lead.Email != null) {
                lead.Email = lead.Email.trim().toLowerCase();
            }

            // Trim Company.
            if (lead.Company != null) {
                lead.Company = lead.Company.trim();
            }

            // Default LeadSource to 'Web' only when blank; keep existing values.
            if (lead.LeadSource == null) {
                lead.LeadSource = 'Web';
            }
        }
    }
}
