public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {
    /**
     * Tracks Opportunities that already received an "Amount changed" Task in this
     * transaction. Static state lives for the duration of the transaction, so when
     * TA_Opportunity_RoundAmount re-updates the same records and re-fires this
     * action, no duplicate Task is created. At most one Task per Opportunity per
     * transaction is produced.
     */
    private static final Set<Id> LOGGED_OPPORTUNITY_IDS = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        List<Task> tasksToCreate = new List<Task>();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity newOpp = triggerNew[i];
            Opportunity oldOpp = triggerOld[i];

            // Skip records already audited in this transaction (e.g. on the
            // re-fired trigger invocation caused by the rounding action).
            if (LOGGED_OPPORTUNITY_IDS.contains(newOpp.Id)) {
                continue;
            }

            // Null-safe comparison: fires when the Amount was added, removed or changed.
            if (newOpp.Amount != oldOpp.Amount) {
                LOGGED_OPPORTUNITY_IDS.add(newOpp.Id);
                tasksToCreate.add(
                    new Task(
                        Subject = 'Amount changed',
                        Status = 'Completed',
                        WhatId = newOpp.Id
                    )
                );
            }
        }

        // One DML statement per trigger execution, bulk-safe for up to 200 records.
        if (!tasksToCreate.isEmpty()) {
            insert tasksToCreate;
        }
    }
}
