/**
 * Shared query cache for Contact trigger actions.
 *
 * The Trigger Actions Framework (TAF) recommends that when multiple trigger actions
 * need the same related data, the data should be loaded once per trigger execution
 * by a dedicated "Service" action that runs first, and shared via a singleton so
 * the other actions never query for themselves. Because Apex static state lives
 * for the whole transaction, the Service action reloads the map on every trigger
 * execution — later DML in the same transaction can involve different Accounts,
 * so the cached map must never be considered stale-safe.
 */
public inherited sharing class TA_Contact_Queries {

	private static TA_Contact_Queries instance;

	/** Parent Accounts for the records of the current trigger execution, keyed by Id. */
	public Map<Id, Account> accountsById;

	private TA_Contact_Queries() {}

	public static TA_Contact_Queries getInstance() {
		if (instance == null) {
			instance = new TA_Contact_Queries();
		}
		return instance;
	}

	/**
	 * Runs first (Order__c 1) in before insert on Contact and (re)loads the
	 * parent Account map for every trigger execution.
	 */
	public inherited sharing class Service implements TriggerAction.BeforeInsert {

		public void beforeInsert(List<sObject> newList) {
			Set<Id> accountIds = new Set<Id>();
			for (sObject record : newList) {
				Contact contact = (Contact) record;
				if (contact.AccountId != null) {
					accountIds.add(contact.AccountId);
				}
			}

			TA_Contact_Queries.getInstance().accountsById = accountIds.isEmpty()
				? new Map<Id, Account>()
				: new Map<Id, Account>([
						SELECT Id,
							BillingStreet,
							BillingCity,
							BillingPostalCode,
							BillingCountry,
							AccountSource
						FROM Account
						WHERE Id IN :accountIds
					]);
		}
	}
}
