/**
 * Before insert on Contact: when a new contact has a parent Account and all four
 * mailing address fields are blank, copy the Account's billing address into them.
 * Contacts without an Account, or with any mailing field filled in, are left alone.
 *
 * Relies on TA_Contact_Queries.Service (Order__c 1) having populated the shared
 * Account map; this action never queries.
 */
public inherited sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {

	public void beforeInsert(List<sObject> newList) {
		Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

		for (sObject record : newList) {
			Contact contact = (Contact) record;

			if (contact.AccountId == null) {
				continue;
			}
			if (String.isNotBlank(contact.MailingStreet) ||
				String.isNotBlank(contact.MailingCity) ||
				String.isNotBlank(contact.MailingPostalCode) ||
				String.isNotBlank(contact.MailingCountry)) {
				continue;
			}
			Account account = accountsById == null ? null : accountsById.get(contact.AccountId);
			if (account == null) {
				continue;
			}

			contact.MailingStreet = account.BillingStreet;
			contact.MailingCity = account.BillingCity;
			contact.MailingPostalCode = account.BillingPostalCode;
			contact.MailingCountry = account.BillingCountry;
		}
	}
}
