/**
 * Before insert on Contact: when a new contact has a parent Account and a blank
 * LeadSource, default it to the Account's AccountSource. Contacts without an
 * Account, or with LeadSource already set, are left alone.
 *
 * Relies on TA_Contact_Queries.Service (Order__c 1) having populated the shared
 * Account map; this action never queries.
 */
public inherited sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {

	public void beforeInsert(List<sObject> newList) {
		Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

		for (sObject record : newList) {
			Contact contact = (Contact) record;

			if (contact.AccountId == null || String.isNotBlank(contact.LeadSource)) {
				continue;
			}
			Account account = accountsById == null ? null : accountsById.get(contact.AccountId);
			if (account == null) {
				continue;
			}

			contact.LeadSource = account.AccountSource;
		}
	}
}
